            <button type="button" onClick={handleAddDynamicItem(setFeaturesAr)} className="flex items-center gap-1.5 text-xs font-bold text-[#0f7a6c] hover:text-[#0d6b5e] transition-colors">
               <Plus size={14} /> إضافة ميزة عربي
            </button>
