        </div>

        <div className="text-start">
          <label className="block text-sm font-bold text-slate-800 dark:text-white mb-3">
            {isRtl ? 'مميزات المنهج (إنجليزي)' : 'Features (English)'}
          </label>
          <div className="space-y-3">
