          }`}
        >
          <span
            className={`inline-block h-4 w-4 transform rounded-full bg-white shadow transition-transform ${
              showOnWebsite
                ? (isRtl ? '-translate-x-6' : 'translate-x-6')
                : (isRtl ? '-translate-x-1' : 'translate-x-1')
            }`}
          />
        </button>
      </div>

      <div className="flex justify-end gap-3 pt-2">
        <button
