import { useState, useRef, useEffect } from 'react'
import { createPortal } from 'react-dom'
import { useTranslation } from 'react-i18next'
import { X, Upload, File, Link as LinkIcon } from 'lucide-react'
import { toast } from 'react-hot-toast'

export default function FileModal({ isOpen, onClose, isSaving, onSubmit }) {
  const { i18n } = useTranslation()
  const isRtl = i18n.language.startsWith('ar')

  const [resourceType, setResourceType] = useState('file')
  const [nameAr, setNameAr] = useState('')
  const [nameEn, setNameEn] = useState('')
  const [url, setUrl] = useState('')
  const [file, setFile] = useState(null)
  const fileInputRef = useRef(null)

  useEffect(() => {
    if (isOpen) {
      setResourceType('file')
      setNameAr('')
      setNameEn('')
      setUrl('')
      setFile(null)
    }
  }, [isOpen])

  if (!isOpen) return null

  const formatUrl = (rawUrl) => {
    let trimmed = (rawUrl || '').trim()
    if (!trimmed) return ''
    if (!/^https?:\/\//i.test(trimmed)) {
      trimmed = `https://${trimmed}`
    }
    return trimmed
  }

  const handleSubmit = (e) => {
    e.preventDefault()

    const cleanNameAr = nameAr.trim() || nameEn.trim()
    const cleanNameEn = nameEn.trim() || nameAr.trim()

    if (!cleanNameAr && !cleanNameEn) {
      toast.error(isRtl ? 'يرجى إدخال عنوان المحتوى' : 'Please enter resource title')
      return
    }

    if (resourceType === 'file') {
      if (!file) {
        toast.error(isRtl ? 'يرجى اختيار ملف' : 'Please select a file')
        return
      }

      const formData = new FormData()
      formData.append('type', 'file')
      formData.append('name[ar]', cleanNameAr)
      formData.append('name[en]', cleanNameEn)
      formData.append('file', file)

      onSubmit(formData)
      return
    }

    if (resourceType === 'link') {
      const normalizedUrl = formatUrl(url)
      if (!normalizedUrl) {
        toast.error(isRtl ? 'يرجى إدخال رابط صالح' : 'Please enter a valid URL')
        return
      }

      const formData = new FormData()
      formData.append('type', 'link')
      formData.append('name[ar]', cleanNameAr)
      formData.append('name[en]', cleanNameEn)
      formData.append('url', normalizedUrl)

      onSubmit(formData)
    }
  }

  return createPortal(
    <div className="fixed inset-0 z-[99999] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
      <div className="bg-white dark:bg-slate-900 rounded-3xl shadow-2xl w-full max-w-lg overflow-hidden flex flex-col" dir={isRtl ? 'rtl' : 'ltr'}>
        <div className="p-5 border-b border-slate-100 dark:border-slate-800/60 flex items-center justify-between">
          <h2 className="text-lg font-bold text-slate-800 dark:text-white">
            {isRtl ? 'إضافة محتوى / مصادر للوحدة' : 'Add Unit Content / Resource'}
          </h2>
          <button onClick={onClose} className="p-2 text-slate-400 hover:text-slate-600 bg-slate-50 rounded-xl hover:bg-slate-100 dark:bg-slate-800 dark:hover:bg-slate-700 transition-colors">
            <X size={20} />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-6 space-y-5 text-start">
           <div className="flex bg-slate-100 dark:bg-slate-800/60 p-1 rounded-2xl gap-1">
            <button
              type="button"
              onClick={() => setResourceType('file')}
              className={`flex-1 py-2 rounded-xl text-xs font-bold transition-all flex items-center justify-center gap-2 cursor-pointer ${resourceType === 'file' ? 'bg-white dark:bg-slate-700 text-[#0f7a6c] dark:text-emerald-400 shadow-sm' : 'text-slate-500 hover:text-slate-700 dark:text-slate-400'}`}
            >
              <File size={16} />
              {isRtl ? 'ملف (PDF / صورة)' : 'File (PDF / Image)'}
            </button>
            <button
              type="button"
              onClick={() => setResourceType('link')}
              className={`flex-1 py-2 rounded-xl text-xs font-bold transition-all flex items-center justify-center gap-2 cursor-pointer ${resourceType === 'link' ? 'bg-white dark:bg-slate-700 text-[#0f7a6c] dark:text-emerald-400 shadow-sm' : 'text-slate-500 hover:text-slate-700 dark:text-slate-400'}`}
            >
              <LinkIcon size={16} />
              {isRtl ? 'رابط خارجي' : 'External Link'}
            </button>
          </div>

          {resourceType === 'file' ? (
            <>
              <div
                onClick={() => fileInputRef.current?.click()}
                className={`w-full h-32 rounded-2xl border-2 border-dashed flex flex-col items-center justify-center cursor-pointer transition-colors ${file ? 'border-[#0f7a6c] bg-[#0f7a6c]/5' : 'border-slate-200 dark:border-slate-700 bg-slate-50 dark:bg-slate-800/50 hover:bg-slate-100 dark:hover:bg-slate-800'}`}
              >
                {file ? (
                  <div className="flex flex-col items-center text-[#0f7a6c]">
                    <File size={32} className="mb-2" />
                    <span className="text-sm font-bold line-clamp-1 px-4">{file.name}</span>
                    <span className="text-xs opacity-70 mt-1">{(file.size / 1024 / 1024).toFixed(2)} MB</span>
                  </div>
                ) : (
                  <div className="flex flex-col items-center text-slate-400">
                    <Upload size={32} className="mb-2" />
                    <span className="text-sm font-semibold">{isRtl ? 'اضغط لاختيار ملف' : 'Click to select a file'}</span>
                  </div>
                )}
              </div>
              <input
                type="file"
                ref={fileInputRef}
                onChange={(e) => e.target.files[0] && setFile(e.target.files[0])}
                className="hidden"
              />
            </>
          ) : (
            <div>
              <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1.5">
                {isRtl ? 'الرابط (URL)' : 'Resource URL'} <span className="text-red-500">*</span>
              </label>
              <div className="relative">
                <input
                  type="text"
                  inputMode="url"
                  required
                  value={url}
                  onChange={(e) => setUrl(e.target.value)}
                  onBlur={(e) => {
                    if (e.target.value.trim()) {
                      setUrl(formatUrl(e.target.value))
                    }
                  }}
                  className="w-full bg-[#f3f7f6] dark:bg-slate-950 border border-transparent focus:border-[#0f7a6c]/20 focus:bg-white text-slate-800 dark:text-slate-100 rounded-xl py-2.5 px-4 outline-none transition-all text-sm font-mono"
                  placeholder="https://drive.google.com/... or https://..."
                  dir="ltr"
                />
              </div>
              <p className="text-[11px] text-slate-400 mt-1">
                {isRtl ? 'مثال: رابط Google Drive، YouTube، أو أي موقع خارجي' : 'Example: Google Drive, YouTube, or any external website'}
              </p>
            </div>
          )}

          <div>
            <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1.5">
              {isRtl ? 'عنوان المحتوى (عربي)' : 'Title (Arabic)'} <span className="text-red-500">*</span>
            </label>
            <input
              type="text"
              required
              value={nameAr}
              onChange={(e) => setNameAr(e.target.value)}
              className="w-full bg-[#f3f7f6] dark:bg-slate-950 border border-transparent focus:border-[#0f7a6c]/20 focus:bg-white text-slate-800 dark:text-slate-100 rounded-xl py-2.5 px-4 outline-none transition-all text-sm"
              placeholder={isRtl ? 'مثال: كتاب الشرح أو رابط المحاضرة' : 'e.g. Explanation Book or Lecture Link'}
            />
          </div>

          <div>
            <label className="block text-xs font-bold text-slate-500 dark:text-slate-400 mb-1.5">
              {isRtl ? 'عنوان المحتوى (إنجليزي)' : 'Title (English)'}
            </label>
            <input
              type="text"
              value={nameEn}
              onChange={(e) => setNameEn(e.target.value)}
              className="w-full bg-[#f3f7f6] dark:bg-slate-950 border border-transparent focus:border-[#0f7a6c]/20 focus:bg-white text-slate-800 dark:text-slate-100 rounded-xl py-2.5 px-4 outline-none transition-all text-sm"
              placeholder={isRtl ? 'e.g. Explanation Book' : 'e.g. Explanation Book'}
            />
          </div>

          <div className="flex justify-end gap-3 pt-4 border-t border-slate-100 dark:border-slate-800">
            <button type="button" onClick={onClose} disabled={isSaving} className="px-5 py-2.5 bg-slate-100 hover:bg-slate-200 text-slate-700 font-bold text-xs rounded-xl transition-all cursor-pointer">
              {isRtl ? 'إلغاء' : 'Cancel'}
            </button>
            <button
              type="submit"
              disabled={isSaving || (resourceType === 'file' && !file) || (resourceType === 'link' && !url.trim())}
              className="px-6 py-2.5 bg-[#0f7a6c] hover:bg-[#0d6b5e] text-white font-bold text-xs rounded-xl transition-all shadow-sm flex items-center gap-2 disabled:opacity-50 cursor-pointer"
            >
              {isSaving && <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin" />}
              {isRtl ? 'حفظ وإضافة' : 'Save & Add'}
            </button>
          </div>
        </form>
      </div>
    </div>,
    document.body
  )
}

import { useState, useEffect, useCallback } from 'react'
import { Calendar, ChevronLeft, ChevronRight, Loader2 } from 'lucide-react'
import { useTranslation } from 'react-i18next'
import Spinner from '@/shared/components/Spinner'
import { adminEarningsApi } from '@/shared/services/api/adminEarningsApi'
import EarningsStats from './components/EarningsStats'
import TeacherEarningsList from './components/TeacherEarningsList'
import WithdrawalRequests from './components/WithdrawalRequests'

export default function AdminEarnings() {
  const { i18n } = useTranslation()
  const isRtl = i18n.language.startsWith('ar')

  const [currentDate, setCurrentDate] = useState(new Date(2026, 0, 1))
  const [stats, setStats] = useState(null)
  const [teachers, setTeachers] = useState([])
  const [requests, setRequests] = useState([])
  const [loading, setLoading] = useState(true)

  const loadData = useCallback(async () => {
    setLoading(true)
    const monthStr = `${currentDate.getFullYear()}-${String(currentDate.getMonth() + 1).padStart(2, '0')}`
    const [statsRes, teachersRes, requestsRes] = await Promise.all([
      adminEarningsApi.fetchEarningsStats(monthStr),
      adminEarningsApi.fetchTeacherEarnings(monthStr),
      adminEarningsApi.fetchWithdrawalRequests(),
    ])

    if (statsRes?.data) setStats(statsRes.data)
    if (teachersRes?.data) setTeachers(teachersRes.data)
    if (requestsRes?.data) setRequests(requestsRes.data)
    setLoading(false)
  }, [currentDate])

  useEffect(() => {
    loadData()
  }, [loadData])

  const handlePrevMonth = () => {
    setCurrentDate((prev) => new Date(prev.getFullYear(), prev.getMonth() - 1, 1))
  }

  const handleNextMonth = () => {
    setCurrentDate((prev) => new Date(prev.getFullYear(), prev.getMonth() + 1, 1))
  }

  const formatMonth = () => {
    const options = { month: 'long', year: 'numeric' }
    return currentDate.toLocaleDateString(isRtl ? 'ar-EG' : 'en-US', options)
  }

  const handleApprove = async (id, proofImage) => {
    const res = await adminEarningsApi.approveWithdrawal(id, proofImage)
    if (res?.success) {
      setRequests((prev) =>
        prev.map((req) => (req.id === id ? { ...req, status: 'paid', proofImage: proofImage || 'https://via.placeholder.com/150' } : req))
      )
    }
  }

  const handleReject = async (id) => {
    const res = await adminEarningsApi.rejectWithdrawal(id)
    if (res?.success) {
      setRequests((prev) =>
        prev.map((req) => (req.id === id ? { ...req, status: 'rejected' } : req))
      )
    }
  }

  if (loading && !stats) {
    return (
      <div className="flex items-center justify-center h-60">
        <Spinner />
      </div>
    )
  }

  return (
    <div className="space-y-8">
      <div className="flex items-center justify-between">
        <button
          aria-label={isRtl ? 'اختر التاريخ' : 'Select Date'}
          className="p-2.5 bg-teal-50 dark:bg-teal-950/20 text-[#0f7a6c] dark:text-emerald-400 rounded-xl hover:opacity-90 active:scale-95 transition-all shadow-sm"
        >
          <Calendar size={20} />
        </button>

        <div className="flex items-center gap-4 bg-white dark:bg-slate-900 px-4 py-2 rounded-2xl border border-slate-100 dark:border-slate-800/60 shadow-sm">
          <button
            onClick={isRtl ? handlePrevMonth : handleNextMonth}
            disabled={loading}
            aria-label={isRtl ? 'الشهر السابق' : 'Previous Month'}
            className="p-1 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-800 text-slate-400 hover:text-slate-600 transition-colors disabled:opacity-50"
          >
            <ChevronRight size={18} />
          </button>
          <span className="text-sm font-bold text-slate-800 dark:text-white min-w-[90px] text-center flex items-center justify-center gap-1.5">
            {loading && <Loader2 size={14} className="animate-spin text-[#0f7a6c]" />}
            {formatMonth()}
          </span>
          <button
            onClick={isRtl ? handleNextMonth : handlePrevMonth}
            disabled={loading}
            aria-label={isRtl ? 'الشهر التالي' : 'Next Month'}
            className="p-1 rounded-lg hover:bg-slate-50 dark:hover:bg-slate-800 text-slate-400 hover:text-slate-600 transition-colors disabled:opacity-50"
          >
            <ChevronLeft size={18} />
          </button>
        </div>
      </div>

      {stats && <EarningsStats stats={stats} />}

      {teachers.length > 0 && <TeacherEarningsList teachers={teachers} />}

      <WithdrawalRequests
        requests={requests}
        onApprove={handleApprove}
        onReject={handleReject}
      />
    </div>
  )
}

import { useState, useEffect, useMemo, useCallback } from 'react'
import { useTranslation } from 'react-i18next'
import {
  Search,
  Plus,

  Layers,
  ChevronLeft,
  ChevronRight,

} from 'lucide-react'
import { adminGroupsApi } from '@/shared/services/api/adminGroupsApi'
import { showDeleteConfirm, showSuccessToast, showErrorToast } from '@/shared/utils/sweetAlert'
import AddEditGroupScreen from './components/AddEditGroupScreen'
import AddStudentsModal from './components/AddStudentsModal'
import ChangeTeacherModal from './components/ChangeTeacherModal'
import Spinner from '@/shared/components/Spinner'

import { getLocalizedValue } from './utils/groupUtils'
import GroupCard from './components/GroupCard'
import GroupDetailsModal from './components/GroupDetailsModal'

export default function AdminGroups() {
  const { t, i18n } = useTranslation()
  const isRtl = i18n.language.startsWith('ar')

  const [viewMode, setViewMode] = useState('list')
  const [groups, setGroups] = useState([])
  const [pagination, setPagination] = useState(null)
  const [isLoading, setIsLoading] = useState(true)
  const [selectedGroup, setSelectedGroup] = useState(null)
  const [searchQuery, setSearchQuery] = useState('')
  const [statusFilter, setStatusFilter] = useState('all')
  const [currentPage, setCurrentPage] = useState(1)
  const [showStudentsModal, setShowStudentsModal] = useState(false)
  const [showAddStudentsModal, setShowAddStudentsModal] = useState(false)
  const [showChangeTeacherModal, setShowChangeTeacherModal] = useState(false)
  const [groupForTeacherChange, setGroupForTeacherChange] = useState(null)

  const itemsPerPage = 10

  const STATUS_FILTER_KEYS = useMemo(() => [
    { key: 'all', label: t('adminDashboard.groups.filterAll', 'الكل'), matchVal: 'الكل' },
    { key: 'pending', label: t('adminDashboard.groups.pendingGroups', 'قيد الانتظار'), matchVal: 'قيد الانتظار' },
    { key: 'active', label: t('adminDashboard.groups.activeGroups', 'النشطة'), matchVal: 'نشط' },
    { key: 'suspended', label: t('adminDashboard.groups.suspendedGroups', 'المتوقفة مؤقتاً'), matchVal: 'متوقف' },
    { key: 'completed', label: t('adminDashboard.groups.completedGroups', 'المكتملة'), matchVal: 'مكتمل' },
  ], [t])

  const loadGroups = useCallback(async () => {
    setIsLoading(true)
    try {
      const params = {
        page: currentPage,
        limit: itemsPerPage,
      }
      if (searchQuery.trim()) {
        params.search = searchQuery.trim()
      }
      if (statusFilter !== 'all') {
        params.status = statusFilter
      }

      const res = await adminGroupsApi.fetchGroups(params)
      const data = res?.data || res
      const rawList = Array.isArray(data) ? data : (Array.isArray(res) ? res : [])
      const items = rawList.map((g) => ({
        ...g,
        id: g.id || g._id,
        _id: g._id || g.id,
      }))

      setGroups(items)

      if (res?.pagination) {
        setPagination(res.pagination)
      } else {
        setPagination(null)
      }
    } catch (err) {
      console.error('Failed to fetch groups:', err)
    } finally {
      setIsLoading(false)
    }
  }, [currentPage, searchQuery, statusFilter, itemsPerPage])

  useEffect(() => {
    loadGroups()
  }, [loadGroups])

  const filtered = useMemo(() => {
    let result = groups

    if (statusFilter !== 'all' && !pagination) {
      result = result.filter((g) => {
        const s = String(g.status || '').toLowerCase()
        if (statusFilter === 'pending') return s.includes('انتظار') || s === 'pending' || s === 'waiting'
        if (statusFilter === 'active') return s.includes('نشط') || s === 'active'
        if (statusFilter === 'suspended') return s.includes('توقف') || s === 'suspended' || s === 'paused'
        if (statusFilter === 'completed') return s.includes('مكتمل') || s === 'completed'
        return g.status === statusFilter
      })
    }

    if (searchQuery.trim() && !pagination) {
      const q = searchQuery.toLowerCase()
      result = result.filter((g) => {
        const name = getLocalizedValue(g.name, isRtl).toLowerCase()
        const teacher = (getLocalizedValue(g.teacher?.name, isRtl) || (typeof g.teacher === 'string' ? g.teacher : '')).toLowerCase()
        const curriculum = getLocalizedValue(g.curriculum?.name || g.subject, isRtl).toLowerCase()
        const level = getLocalizedValue(g.studentLevel?.name || g.level, isRtl).toLowerCase()
        return name.includes(q) || teacher.includes(q) || curriculum.includes(q) || level.includes(q)
      })
    }

    return result
  }, [groups, statusFilter, searchQuery, pagination, isRtl])

  const metrics = useMemo(() => {
    const total = pagination?.totalCount ?? groups.length
    const pending = groups.filter((g) => {
      const s = String(g.status || '').toLowerCase()
      return s.includes('انتظار') || s === 'pending' || s === 'waiting'
    }).length
    const active = groups.filter((g) => {
      const s = String(g.status || '').toLowerCase()
      return s.includes('نشط') || s === 'active'
    }).length
    const suspended = groups.filter((g) => {
      const s = String(g.status || '').toLowerCase()
      return s.includes('توقف') || s === 'suspended' || s === 'paused'
    }).length
    const completed = groups.filter((g) => {
      const s = String(g.status || '').toLowerCase()
      return s.includes('مكتمل') || s === 'completed'
    }).length

    return { total, pending, active, suspended, completed }
  }, [groups, pagination])

  const totalCount = pagination?.totalCount ?? filtered.length
  const totalPages = pagination?.numberOfPages ?? Math.max(1, Math.ceil(totalCount / itemsPerPage))
  const isPaginationDimmed = totalPages <= 1

  const paged = useMemo(() => {
    if (pagination) {
      return filtered
    }
    const start = (currentPage - 1) * itemsPerPage
    return filtered.slice(start, start + itemsPerPage)
  }, [filtered, currentPage, pagination, itemsPerPage])

  const handleSaveGroup = async (formData) => {
    setIsLoading(true)
    try {
      if (viewMode === 'edit-group' && selectedGroup) {
        const targetId = selectedGroup.id || selectedGroup._id
        const res = await adminGroupsApi.updateGroup(targetId, formData)
        const updatedItem = res?.data || res
        if (updatedItem) {
          setGroups((prev) =>
            prev.map((g) => (g.id === targetId || g._id === targetId ? { ...g, ...updatedItem, id: targetId, _id: targetId } : g))
          )
          setSelectedGroup(null)
          setViewMode('list')
          loadGroups()
          showSuccessToast(res?.message || t('adminDashboard.groups.updateSuccess', 'تم تحديث بيانات المجموعة بنجاح'), isRtl)
        }
      } else {
        const res = await adminGroupsApi.createGroup(formData)
        const newItem = res?.data || res
        if (newItem) {
          const normalizedNew = { ...newItem, id: newItem.id || newItem._id, _id: newItem._id || newItem.id }
          setGroups((prev) => [normalizedNew, ...prev])
          setSelectedGroup(null)
          setViewMode('list')
          loadGroups()
          showSuccessToast(res?.message || t('adminDashboard.groups.createSuccess', 'تم إنشاء المجموعة بنجاح'), isRtl)
        }
      }
    } catch (error) {
      console.error('Error saving group:', error)
      showErrorToast(error?.response?.data?.message || t('common.errorOccurred', 'حدث خطأ، يرجى المحاولة مرة أخرى'), isRtl)
    } finally {
      setIsLoading(false)
    }
  }

  const handleDeleteGroup = async (group) => {
    const isConfirmed = await showDeleteConfirm(isRtl, getLocalizedValue(group.name, isRtl))
    if (!isConfirmed) return
    setIsLoading(true)
    const targetId = group.id || group._id
    try {
      const res = await adminGroupsApi.deleteGroup(targetId)
      if (res?.success || res?.status === 200 || res) {
        setGroups((prev) => prev.filter((g) => g.id !== targetId && g._id !== targetId))
        loadGroups()
        showSuccessToast(res?.message || t('adminDashboard.groups.deleteSuccess', 'تم حذف المجموعة بنجاح'), isRtl)
      }
    } catch (error) {
      console.error('Failed to delete group:', error)
      showErrorToast(error?.response?.data?.message || t('adminDashboard.groups.deleteError', 'فشل حذف المجموعة، يرجى المحاولة لاحقاً'), isRtl)
    } finally {
      setIsLoading(false)
    }
  }

  const handleRemoveStudent = async (groupId, studentId, studentName) => {
    const isConfirmed = await showDeleteConfirm(isRtl, studentName)
    if (!isConfirmed) return

    try {
      const res = await adminGroupsApi.removeStudentFromGroup(groupId, studentId)
      if (res?.success || res) {
        setGroups((prev) =>
          prev.map((g) => {
            if (g.id === groupId || g._id === groupId) {
              const list = (g.students || []).filter((s) => {
                const sId = typeof s === 'string' ? s : (s?.id || s?._id || s?.student?._id || s?.student?.id || s?.student)
                return String(sId) !== String(studentId)
              })
              return { ...g, students: list, currentStudentsCount: list.length }
            }
            return g
          })
        )
        if (selectedGroup?.id === groupId || selectedGroup?._id === groupId) {
          setSelectedGroup((prev) => {
            if (!prev) return prev
            const list = (prev.students || []).filter((s) => {
              const sId = typeof s === 'string' ? s : (s?.id || s?._id || s?.student?._id || s?.student?.id || s?.student)
              return String(sId) !== String(studentId)
            })
            return { ...prev, students: list, currentStudentsCount: list.length }
          })
        }
        showSuccessToast(res?.message || t('adminDashboard.groups.removeStudentSuccess', 'تمت إزالة الطالب من المجموعة بنجاح'), isRtl)
      }
    } catch (error) {
      console.error('Failed to remove student:', error)
      showErrorToast(error?.response?.data?.message || t('adminDashboard.groups.removeStudentError', 'فشل إزالة الطالب من المجموعة'), isRtl)
    }
  }

  const handleEditGroup = async (group) => {
    setIsLoading(true)
    const groupId = group.id || group._id
    try {
      const res = await adminGroupsApi.fetchGroupByIdRaw(groupId)
      const data = res?.data || res
      if (data && (data.id || data._id || data.name)) {
        setSelectedGroup({
          ...group,
          ...data,
          id: data.id || data._id || groupId,
          _id: data._id || data.id || groupId,
        })
      } else {
        setSelectedGroup({ ...group, id: groupId, _id: groupId })
      }
    } catch (err) {
      console.warn('Error fetching raw group for edit, using card data:', err)
      setSelectedGroup({ ...group, id: groupId, _id: groupId })
    } finally {
      setIsLoading(false)
      setViewMode('edit-group')
    }
  }

  const handleViewStudents = async (group) => {
    const groupId = group.id || group._id
    const normalizedGroup = { ...group, id: groupId, _id: groupId }
    setSelectedGroup(normalizedGroup)
    setShowStudentsModal(true)
    try {
      const res = await adminGroupsApi.fetchGroupByIdLocalized(groupId)
      const detailedGroup = res?.data || res
      if (detailedGroup && (detailedGroup.students || detailedGroup.id || detailedGroup._id)) {
        setSelectedGroup((prev) => ({
          ...prev,
          ...detailedGroup,
          id: detailedGroup.id || detailedGroup._id || groupId,
          _id: detailedGroup._id || detailedGroup.id || groupId,
        }))
      }
    } catch (err) {
      console.warn('Could not load detailed localized group data:', err)
    }
  }

  const handleAddSingleStudent = async (groupId, student) => {
    try {
      setIsLoading(true)
      const res = await adminGroupsApi.addStudentToGroup(groupId, student)
      const detailRes = await adminGroupsApi.fetchGroupByIdLocalized(groupId)
      const detailedGroup = detailRes?.data || detailRes
      if (detailedGroup) {
        setGroups((prev) => prev.map((g) => (g.id === groupId ? { ...g, ...detailedGroup } : g)))
        setSelectedGroup(detailedGroup)
      }
      loadGroups()
      showSuccessToast(res?.message || t('adminDashboard.groups.addStudentSuccess', 'تمت إضافة الطالب إلى المجموعة بنجاح'), isRtl)
    } catch (error) {
      console.error('Failed to add student to group:', error)
      showErrorToast(error?.response?.data?.message || t('adminDashboard.groups.addStudentError', 'فشل إضافة الطالب إلى المجموعة'), isRtl)
    } finally {
      setIsLoading(false)
    }
  }

  const handleAddStudents = async (students) => {
    if (!students || students.length === 0) return
    setIsLoading(true)
    try {
      for (const student of students) {
        await adminGroupsApi.addStudentToGroup(selectedGroup.id, student)
      }
      const res = await adminGroupsApi.fetchGroupByIdLocalized(selectedGroup.id)
      const detailedGroup = res?.data || res
      if (detailedGroup) {
        setGroups((prev) => prev.map((g) => (g.id === selectedGroup.id ? { ...g, ...detailedGroup } : g)))
        setSelectedGroup(detailedGroup)
      }
      loadGroups()
      showSuccessToast(t('adminDashboard.groups.addStudentsSuccess', 'تمت إضافة الطلاب إلى المجموعة بنجاح'), isRtl)
      setShowAddStudentsModal(false)
    } catch (error) {
      console.error('Failed to add students:', error)
      showErrorToast(error?.response?.data?.message || t('adminDashboard.groups.addStudentsError', 'فشل إضافة الطلاب إلى المجموعة'), isRtl)
    } finally {
      setIsLoading(false)
    }
  }

  const handleOpenChangeTeacher = (group) => {
    setGroupForTeacherChange(group)
    setShowChangeTeacherModal(true)
  }

  const handleChangeTeacher = async (teacherId, teacherObj) => {
    if (!groupForTeacherChange) return
    const groupId = groupForTeacherChange.id
    setIsLoading(true)
    try {
      const teacherName = typeof teacherObj?.name === 'object'
        ? (teacherObj.name.ar || teacherObj.name.en)
        : (teacherObj?.name || 'المعلم الجديد')

      const res = await adminGroupsApi.changeTeacher(groupId, {
        teacher: teacherId,
        teacherId,
        name: teacherName,
        email: teacherObj?.email,
        phone: teacherObj?.phone,
      })

      const newTeacherData = {
        id: teacherId,
        name: teacherName,
        email: teacherObj?.email || '',
        phone: teacherObj?.phone || '',
      }

      setGroups((prev) =>
        prev.map((g) => (String(g.id) === String(groupId) ? { ...g, teacher: newTeacherData } : g))
      )

      if (selectedGroup && String(selectedGroup.id) === String(groupId)) {
        setSelectedGroup((prev) => (prev ? { ...prev, teacher: newTeacherData } : prev))
      }

      loadGroups()
      showSuccessToast(
        res?.message || t('adminDashboard.groups.changeTeacherSuccess', 'تم تغيير معلم المجموعة بنجاح'),
        isRtl
      )
    } catch (error) {
      console.error('Failed to change group teacher:', error)
      showErrorToast(
        error?.response?.data?.message || t('adminDashboard.groups.changeTeacherError', 'فشل تغيير معلم المجموعة'),
        isRtl
      )
    } finally {
      setIsLoading(false)
    }
  }

  if (viewMode === 'add-group' || viewMode === 'edit-group') {
    return (
      <AddEditGroupScreen
        group={viewMode === 'edit-group' ? selectedGroup : null}
        isRtl={isRtl}
        t={t}
        isSaving={isLoading}
        onSave={handleSaveGroup}
        onCancel={() => {
          setSelectedGroup(null)
          setViewMode('list')
        }}
      />
    )
  }

  const startIdx = totalCount > 0 ? (currentPage - 1) * itemsPerPage + 1 : 0
  const endIdx = totalCount > 0 ? Math.min(currentPage * itemsPerPage, totalCount) : 0

  return (
    <div className="space-y-6 p-1 md:p-6 relative" dir={isRtl ? 'rtl' : 'ltr'}>
      {isLoading && (
        <div className="absolute inset-0 z-50 flex items-center justify-center bg-white/50 dark:bg-slate-900/50 backdrop-blur-sm rounded-3xl">
          <Spinner />
        </div>
      )}
      <div className="text-start">
        <h1 className="text-2xl font-bold text-slate-800 dark:text-white">
          {t('adminDashboard.groups.title', 'إدارة المجموعات')}
        </h1>
        <p className="text-sm text-slate-400 dark:text-slate-500 mt-1">
          {t('adminDashboard.groups.subtitle', 'منارة العز أكاديمي · لوحة الإدارة')}
        </p>
      </div>

       <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-4">
        {[
          { label: t('adminDashboard.groups.totalGroups', 'إجمالي المجموعات'), value: metrics.total, cls: 'text-slate-700 dark:text-slate-200' },
          { label: t('adminDashboard.groups.pendingGroups', 'قيد الانتظار'), value: metrics.pending, cls: 'text-blue-600 dark:text-blue-400' },
          { label: t('adminDashboard.groups.activeGroups', 'النشطة'), value: metrics.active, cls: 'text-emerald-600 dark:text-emerald-400' },
          { label: t('adminDashboard.groups.suspendedGroups', 'المتوقفة مؤقتاً'), value: metrics.suspended, cls: 'text-amber-600 dark:text-amber-400' },
          { label: t('adminDashboard.groups.completedGroups', 'المكتملة'), value: metrics.completed, cls: 'text-purple-600 dark:text-purple-400' },
        ].map((m) => (
          <div
            key={m.label}
            className="flex flex-col items-center justify-center gap-1 p-5 bg-white dark:bg-slate-900 rounded-3xl border border-slate-100 dark:border-slate-800/60 shadow-soft"
          >
            <span className={`text-3xl font-extrabold ${m.cls}`}>{m.value}</span>
            <span className="text-xs font-semibold text-slate-400 dark:text-slate-500 text-center">{m.label}</span>
          </div>
        ))}
      </div>

       <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3 p-4 bg-white dark:bg-slate-900 rounded-3xl border border-slate-100 dark:border-slate-800/60 shadow-soft">
        <div className="flex items-center gap-3 flex-wrap">
          <button
            onClick={() => {
              setSelectedGroup(null)
              setViewMode('add-group')
            }}
            className="flex items-center gap-2 px-5 py-2.5 rounded-2xl bg-brand-500 hover:bg-brand-600 text-white text-sm font-semibold transition-all shadow-md shadow-brand-500/20 active:scale-[0.98] cursor-pointer"
          >
            <Plus size={18} />
            <span>{t('adminDashboard.groups.addGroup', 'إضافة مجموعة')}</span>
          </button>
          <div className="flex items-center gap-1.5 flex-wrap">
            {STATUS_FILTER_KEYS.map((f) => (
              <button
                key={f.key}
                onClick={() => {
                  setStatusFilter(f.key)
                  setCurrentPage(1)
                }}
                className={`px-3 py-1.5 rounded-xl text-xs font-bold transition-all cursor-pointer ${statusFilter === f.key
                    ? 'bg-brand-500 text-white shadow-sm'
                    : 'bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-700'
                  }`}
              >
                {f.label}
              </button>
            ))}
          </div>
        </div>
        <div className="relative w-full sm:w-64">
          <Search size={16} className={`absolute ${isRtl ? 'right-3' : 'left-3'} top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none`} />
          <input
            type="text"
            placeholder={t('adminDashboard.groups.searchPlaceholder', 'بحث في المجموعات...')}
            value={searchQuery}
            onChange={(e) => {
              setSearchQuery(e.target.value)
              setCurrentPage(1)
            }}
            className={`w-full bg-[#f3f7f6] dark:bg-slate-800 rounded-2xl py-2.5 ${isRtl ? 'pr-9 pl-4' : 'pl-9 pr-4'} text-sm text-slate-700 dark:text-slate-200 outline-none border border-transparent focus:border-brand-400 transition-colors placeholder-slate-400`}
          />
        </div>
      </div>

       {paged.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-20 gap-3 text-slate-400 bg-white dark:bg-slate-900 rounded-3xl border border-slate-100 dark:border-slate-800/60">
          <Layers size={48} strokeWidth={1.5} />
          <p className="text-sm font-medium">{t('adminDashboard.groups.noGroupsFound', 'لا توجد مجموعات مطابقة')}</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-5">
          {paged.map((group) => (
            <GroupCard
              key={group.id}
              group={group}
              onEdit={handleEditGroup}
              onViewStudents={handleViewStudents}
              onDelete={handleDeleteGroup}
              onChangeTeacher={handleOpenChangeTeacher}
              t={t}
              isRtl={isRtl}
            />
          ))}
        </div>
      )}

       <div
        className={`flex flex-col sm:flex-row items-center justify-between gap-4 p-5 bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 rounded-3xl shadow-soft mt-6 transition-opacity duration-300 ${isPaginationDimmed ? 'opacity-40 pointer-events-none select-none' : ''
          }`}
      >
        <div className="text-sm text-slate-400 dark:text-slate-500 font-medium">
          {isRtl ? (
            <>
              {t('adminDashboard.students.pagination.showing', 'عرض')}{' '}
              <span className="font-semibold text-slate-700 dark:text-slate-200">{startIdx}</span>{' '}
              {t('adminDashboard.students.pagination.to', 'إلى')}{' '}
              <span className="font-semibold text-slate-700 dark:text-slate-200">{endIdx}</span>{' '}
              {t('adminDashboard.students.pagination.of', 'من أصل')}{' '}
              <span className="font-semibold text-slate-700 dark:text-slate-200">{totalCount}</span>{' '}
              {t('adminDashboard.groups.title', 'مجموعات')}
            </>
          ) : (
            <>
              {t('adminDashboard.students.pagination.showing', 'Showing')}{' '}
              <span className="font-semibold text-slate-700 dark:text-slate-200">{startIdx}</span>{' '}
              {t('adminDashboard.students.pagination.to', 'to')}{' '}
              <span className="font-semibold text-slate-700 dark:text-slate-200">{endIdx}</span>{' '}
              {t('adminDashboard.students.pagination.of', 'of')}{' '}
              <span className="font-semibold text-slate-700 dark:text-slate-200">{totalCount}</span>{' '}
              {t('adminDashboard.groups.title', 'groups')}
            </>
          )}
        </div>

        <div className="flex items-center gap-2">
          <button
            type="button"
            onClick={() => setCurrentPage((prev) => Math.max(prev - 1, 1))}
            disabled={currentPage === 1 || isPaginationDimmed}
            className="flex items-center gap-1.5 px-4 py-2 rounded-xl text-xs sm:text-sm font-semibold border border-slate-100 dark:border-slate-800 bg-white hover:bg-slate-50 dark:bg-slate-900 dark:hover:bg-slate-800 text-slate-700 dark:text-slate-300 disabled:opacity-40 disabled:cursor-not-allowed transition-all cursor-pointer"
          >
            {isRtl ? <ChevronRight size={16} aria-hidden="true" /> : <ChevronLeft size={16} aria-hidden="true" />}
          </button>

          <span className="px-3 py-2 rounded-xl text-xs sm:text-sm font-bold border border-slate-100 dark:border-slate-800 bg-white dark:bg-slate-900 text-slate-700 dark:text-slate-300 min-w-[80px] text-center">
            {currentPage} / {totalPages}
          </span>

          <button
            type="button"
            onClick={() => setCurrentPage((prev) => Math.min(prev + 1, totalPages))}
            disabled={currentPage === totalPages || isPaginationDimmed}
            className="flex items-center gap-1.5 px-4 py-2 rounded-xl text-xs sm:text-sm font-semibold border border-slate-100 dark:border-slate-800 bg-white hover:bg-slate-50 dark:bg-slate-900 dark:hover:bg-slate-800 text-slate-700 dark:text-slate-300 disabled:opacity-40 disabled:cursor-not-allowed transition-all cursor-pointer"
          >
            {isRtl ? <ChevronLeft size={16} aria-hidden="true" /> : <ChevronRight size={16} aria-hidden="true" />}
          </button>
        </div>
      </div>

      {showStudentsModal && selectedGroup && (
        <GroupDetailsModal
          group={selectedGroup}
          onClose={() => {
            setShowStudentsModal(false)
            setSelectedGroup(null)
          }}
          onRemoveStudent={handleRemoveStudent}
          onOpenAddStudents={() => {
            setShowStudentsModal(false)
            setShowAddStudentsModal(true)
          }}
          onAddStudent={handleAddSingleStudent}
          onChangeTeacher={handleOpenChangeTeacher}
          t={t}
          isRtl={isRtl}
        />
      )}

      {showAddStudentsModal && selectedGroup && (
        <AddStudentsModal
          group={selectedGroup}
          isRtl={isRtl}
          onAdd={handleAddStudents}
          onCancel={() => setShowAddStudentsModal(false)}
        />
      )}

      {showChangeTeacherModal && groupForTeacherChange && (
        <ChangeTeacherModal
          group={groupForTeacherChange}
          onClose={() => {
            setShowChangeTeacherModal(false)
            setGroupForTeacherChange(null)
          }}
          onConfirm={handleChangeTeacher}
          isRtl={isRtl}
        />
      )}
    </div>
  )
}

import { useState, useEffect, useMemo, useCallback } from 'react'
import { useTranslation } from 'react-i18next'
import {
  Search,
  Plus,
  Layers,
  ChevronLeft,
  ChevronRight,
} from 'lucide-react'
import { adminGroupsApi } from '@/shared/services/api/adminGroupsApi'
import { showDeleteConfirm, showSuccessToast, showErrorToast } from '@/shared/utils/sweetAlert'
import AddEditGroupScreen from './components/AddEditGroupScreen'
import AddStudentsModal from './components/AddStudentsModal'
import ChangeTeacherModal from './components/ChangeTeacherModal'
import Spinner from '@/shared/components/Spinner'
import { getLocalizedValue } from './utils/groupUtils'
import GroupCard from './components/GroupCard'
import GroupDetailsModal from './components/GroupDetailsModal'

const TAB_API_MAP = {
  all: (params) => adminGroupsApi.fetchLocalizedGroups(params),
  pending: (params) => adminGroupsApi.fetchLocalizedPendingGroups(params),
  active: (params) => adminGroupsApi.fetchLocalizedActiveGroups(params),
  stopped: (params) => adminGroupsApi.fetchLocalizedStoppedGroups(params),
  completed: (params) => adminGroupsApi.fetchLocalizedCompletedGroups(params),
}

const TYPE_FILTER_VALUES = ['all', 'public', 'private']

export default function AdminPrivateGroups() {
  const { t, i18n } = useTranslation()
  const isRtl = i18n.language.startsWith('ar')

  const [viewMode, setViewMode] = useState('list')
  const [selectedGroup, setSelectedGroup] = useState(null)
  const [showStudentsModal, setShowStudentsModal] = useState(false)
  const [showAddStudentsModal, setShowAddStudentsModal] = useState(false)
  const [showChangeTeacherModal, setShowChangeTeacherModal] = useState(false)
  const [groupForTeacherChange, setGroupForTeacherChange] = useState(null)

  const [groups, setGroups] = useState([])
  const [statistics, setStatistics] = useState(null)
  const [pagination, setPagination] = useState(null)
  const [isLoading, setIsLoading] = useState(true)

  const [activeTab, setActiveTab] = useState('all')
  const [typeFilter, setTypeFilter] = useState('all')
  const [searchQuery, setSearchQuery] = useState('')
  const [currentPage, setCurrentPage] = useState(1)
  const itemsPerPage = 10

  const STATUS_TABS = useMemo(() => [
    { key: 'all', label: t('adminDashboard.privateGroups.tabs.all', 'الكل') },
    { key: 'pending', label: t('adminDashboard.privateGroups.tabs.pending', 'قيد الانتظار') },
    { key: 'active', label: t('adminDashboard.privateGroups.tabs.active', 'نشطة') },
    { key: 'stopped', label: t('adminDashboard.privateGroups.tabs.stopped', 'متوقفة') },
    { key: 'completed', label: t('adminDashboard.privateGroups.tabs.completed', 'مكتملة') },
  ], [t])

  const TYPE_LABELS = useMemo(() => ({
    all: t('adminDashboard.privateGroups.typeAll', 'الكل'),
    public: t('adminDashboard.groups.typePublic', 'عامة'),
    private: t('adminDashboard.groups.typePrivate', 'خاصة'),
  }), [t])

  const loadGroups = useCallback(async () => {
    setIsLoading(true)
    try {
      const params = { page: currentPage, limit: itemsPerPage }
      if (searchQuery.trim()) params.search = searchQuery.trim()
      if (typeFilter !== 'all') params.type = typeFilter

      const fetcher = TAB_API_MAP[activeTab] ?? TAB_API_MAP.all
      const res = await fetcher(params)

      const rawData = res?.data
      const items = Array.isArray(rawData) ? rawData : (Array.isArray(res) ? res : [])
      setGroups(items)

      if (res?.pagination) setPagination(res.pagination)
      else setPagination(null)

      if (res?.statistics) setStatistics(res.statistics)
    } catch (err) {
      console.error('Failed to fetch private groups:', err)
    } finally {
      setIsLoading(false)
    }
  }, [activeTab, currentPage, searchQuery, typeFilter])

  useEffect(() => {
    loadGroups()
  }, [loadGroups])

  const totalCount = pagination?.totalCount ?? groups.length
  const totalPages = pagination?.numberOfPages ?? Math.max(1, Math.ceil(totalCount / itemsPerPage))
  const isPaginationDimmed = totalPages <= 1
  const startIdx = totalCount > 0 ? (currentPage - 1) * itemsPerPage + 1 : 0
  const endIdx = totalCount > 0 ? Math.min(currentPage * itemsPerPage, totalCount) : 0

  const metrics = useMemo(() => ({
    total: statistics?.total ?? totalCount,
    pending: statistics?.pending ?? 0,
    active: statistics?.active ?? 0,
    stopped: statistics?.stopped ?? 0,
    completed: statistics?.completed ?? 0,
  }), [statistics, totalCount])

  const handleTabChange = useCallback((tabKey) => {
    setActiveTab(tabKey)
    setCurrentPage(1)
  }, [])

  const handleTypeChange = useCallback((typeVal) => {
    setTypeFilter(typeVal)
    setCurrentPage(1)
  }, [])

  const handleSaveGroup = async (formData) => {
    setIsLoading(true)
    try {
      if (viewMode === 'edit-group' && selectedGroup) {
        const res = await adminGroupsApi.updateGroup(selectedGroup.id, formData)
        const updatedItem = res?.data || res
        if (updatedItem) {
          setGroups((prev) => prev.map((g) => (g.id === selectedGroup.id ? { ...g, ...updatedItem } : g)))
          setSelectedGroup(null)
          setViewMode('list')
          loadGroups()
          showSuccessToast(res?.message || t('adminDashboard.groups.updateSuccess', 'تم تحديث بيانات المجموعة بنجاح'), isRtl)
        }
      } else {
        const res = await adminGroupsApi.createGroup(formData)
        const newItem = res?.data || res
        if (newItem) {
          setGroups((prev) => [newItem, ...prev])
          setSelectedGroup(null)
          setViewMode('list')
          loadGroups()
          showSuccessToast(res?.message || t('adminDashboard.groups.createSuccess', 'تم إنشاء المجموعة بنجاح'), isRtl)
        }
      }
    } catch (error) {
      console.error('Error saving group:', error)
      showErrorToast(error?.response?.data?.message || t('common.errorOccurred', 'حدث خطأ، يرجى المحاولة مرة أخرى'), isRtl)
    } finally {
      setIsLoading(false)
    }
  }

  const handleDeleteGroup = async (group) => {
    const isConfirmed = await showDeleteConfirm(isRtl, getLocalizedValue(group.name, isRtl))
    if (!isConfirmed) return
    setIsLoading(true)
    try {
      const res = await adminGroupsApi.deleteGroup(group.id)
      if (res?.success || res?.status === 200 || res) {
        setGroups((prev) => prev.filter((g) => g.id !== group.id))
        loadGroups()
        showSuccessToast(res?.message || t('adminDashboard.groups.deleteSuccess', 'تم حذف المجموعة بنجاح'), isRtl)
      }
    } catch (error) {
      console.error('Failed to delete group:', error)
      showErrorToast(error?.response?.data?.message || t('adminDashboard.groups.deleteError', 'فشل حذف المجموعة، يرجى المحاولة لاحقاً'), isRtl)
    } finally {
      setIsLoading(false)
    }
  }

  const handleEditGroup = async (group) => {
    setIsLoading(true)
    const groupId = group.id || group._id
    try {
      const res = await adminGroupsApi.fetchGroupByIdRaw(groupId)
      const data = res?.data || res
      if (data && (data.id || data._id || data.name)) {
        setSelectedGroup({
          ...group,
          ...data,
          id: data.id || data._id || groupId,
          _id: data._id || data.id || groupId,
        })
      } else {
        setSelectedGroup({ ...group, id: groupId, _id: groupId })
      }
    } catch (err) {
      console.warn('Error fetching raw group for edit, using card data:', err)
      setSelectedGroup({ ...group, id: groupId, _id: groupId })
    } finally {
      setIsLoading(false)
      setViewMode('edit-group')
    }
  }

  const handleViewStudents = async (group) => {
    setSelectedGroup(group)
    setShowStudentsModal(true)
    try {
      const res = await adminGroupsApi.fetchGroupByIdLocalized(group.id)
      const detailedGroup = res?.data || res
      if (detailedGroup && (detailedGroup.students || detailedGroup.id)) {
        setSelectedGroup((prev) => ({ ...prev, ...detailedGroup }))
      }
    } catch (err) {
      console.warn('Could not load detailed localized group data:', err)
    }
  }

  const handleAddSingleStudent = async (groupId, student) => {
    try {
      setIsLoading(true)
      const res = await adminGroupsApi.addStudentToGroup(groupId, student)
      const detailRes = await adminGroupsApi.fetchGroupByIdLocalized(groupId)
      const detailedGroup = detailRes?.data || detailRes
      if (detailedGroup) {
        setGroups((prev) => prev.map((g) => (g.id === groupId ? { ...g, ...detailedGroup } : g)))
        setSelectedGroup(detailedGroup)
      }
      loadGroups()
      showSuccessToast(res?.message || t('adminDashboard.groups.addStudentSuccess', 'تمت إضافة الطالب إلى المجموعة بنجاح'), isRtl)
    } catch (error) {
      console.error('Failed to add student to group:', error)
      showErrorToast(error?.response?.data?.message || t('adminDashboard.groups.addStudentError', 'فشل إضافة الطالب إلى المجموعة'), isRtl)
    } finally {
      setIsLoading(false)
    }
  }

  const handleAddStudents = async (students) => {
    if (!students || students.length === 0) return
    setIsLoading(true)
    try {
      for (const student of students) {
        await adminGroupsApi.addStudentToGroup(selectedGroup.id, student)
      }
      const res = await adminGroupsApi.fetchGroupByIdLocalized(selectedGroup.id)
      const detailedGroup = res?.data || res
      if (detailedGroup) {
        setGroups((prev) => prev.map((g) => (g.id === selectedGroup.id ? { ...g, ...detailedGroup } : g)))
        setSelectedGroup(detailedGroup)
      }
      loadGroups()
      showSuccessToast(t('adminDashboard.groups.addStudentsSuccess', 'تمت إضافة الطلاب إلى المجموعة بنجاح'), isRtl)
      setShowAddStudentsModal(false)
    } catch (error) {
      console.error('Failed to add students:', error)
      showErrorToast(error?.response?.data?.message || t('adminDashboard.groups.addStudentsError', 'فشل إضافة الطلاب إلى المجموعة'), isRtl)
    } finally {
      setIsLoading(false)
    }
  }

  const handleRemoveStudent = async (groupId, studentId, studentName) => {
    const isConfirmed = await showDeleteConfirm(isRtl, studentName)
    if (!isConfirmed) return
    try {
      const res = await adminGroupsApi.removeStudentFromGroup(groupId, studentId)
      if (res?.success || res) {
        setGroups((prev) =>
          prev.map((g) => {
            if (g.id === groupId) {
              const list = (g.students || []).filter((s) => s.id !== studentId)
              return { ...g, students: list, currentStudentsCount: list.length }
            }
            return g
          })
        )
        if (selectedGroup?.id === groupId) {
          setSelectedGroup((prev) => {
            if (!prev) return prev
            const list = (prev.students || []).filter((s) => s.id !== studentId)
            return { ...prev, students: list, currentStudentsCount: list.length }
          })
        }
        showSuccessToast(res?.message || t('adminDashboard.groups.removeStudentSuccess', 'تمت إزالة الطالب من المجموعة بنجاح'), isRtl)
      }
    } catch (error) {
      console.error('Failed to remove student:', error)
      showErrorToast(error?.response?.data?.message || t('adminDashboard.groups.removeStudentError', 'فشل إزالة الطالب من المجموعة'), isRtl)
    }
  }

  const handleOpenChangeTeacher = useCallback((group) => {
    setGroupForTeacherChange(group)
    setShowChangeTeacherModal(true)
  }, [])

  const handleChangeTeacher = async (teacherId, teacherObj) => {
    if (!groupForTeacherChange) return
    const groupId = groupForTeacherChange.id
    setIsLoading(true)
    try {
      const teacherName = typeof teacherObj?.name === 'object'
        ? (teacherObj.name.ar || teacherObj.name.en)
        : (teacherObj?.name || 'المعلم الجديد')
      const res = await adminGroupsApi.changeTeacher(groupId, {
        teacher: teacherId,
        teacherId,
        name: teacherName,
        email: teacherObj?.email,
        phone: teacherObj?.phone,
      })
      const newTeacherData = { id: teacherId, name: teacherName, email: teacherObj?.email || '', phone: teacherObj?.phone || '' }
      setGroups((prev) => prev.map((g) => (String(g.id) === String(groupId) ? { ...g, teacher: newTeacherData } : g)))
      if (selectedGroup && String(selectedGroup.id) === String(groupId)) {
        setSelectedGroup((prev) => (prev ? { ...prev, teacher: newTeacherData } : prev))
      }
      loadGroups()
      showSuccessToast(res?.message || t('adminDashboard.groups.changeTeacherSuccess', 'تم تغيير معلم المجموعة بنجاح'), isRtl)
    } catch (error) {
      console.error('Failed to change group teacher:', error)
      showErrorToast(error?.response?.data?.message || t('adminDashboard.groups.changeTeacherError', 'فشل تغيير معلم المجموعة'), isRtl)
    } finally {
      setIsLoading(false)
    }
  }

  if (viewMode === 'add-group' || viewMode === 'edit-group') {
    return (
      <AddEditGroupScreen
        group={viewMode === 'edit-group' ? selectedGroup : null}
        isRtl={isRtl}
        t={t}
        isSaving={isLoading}
        onSave={handleSaveGroup}
        onCancel={() => {
          setSelectedGroup(null)
          setViewMode('list')
        }}
      />
    )
  }

  return (
    <div className="space-y-6 p-1 md:p-6 relative" dir={isRtl ? 'rtl' : 'ltr'}>
      {isLoading && (
        <div className="absolute inset-0 z-50 flex items-center justify-center bg-white/50 dark:bg-slate-900/50 backdrop-blur-sm rounded-3xl">
          <Spinner />
        </div>
      )}

      <div className="text-start">
        <h1 className="text-2xl font-bold text-slate-800 dark:text-white">
          {t('adminDashboard.privateGroups.title', 'المجموعات الدراسية')}
        </h1>
        <p className="text-sm text-slate-400 dark:text-slate-500 mt-1">
          {t('adminDashboard.groups.subtitle', 'منارة العز أكاديمي · لوحة الإدارة')}
        </p>
      </div>

      <div className="grid grid-cols-2 sm:grid-cols-5 gap-4">
        {[
          { label: t('adminDashboard.privateGroups.tabs.all', 'الكل'), value: metrics.total, cls: 'text-slate-700 dark:text-slate-200', tab: 'all' },
          { label: t('adminDashboard.privateGroups.tabs.pending', 'قيد الانتظار'), value: metrics.pending, cls: 'text-amber-500 dark:text-amber-400', tab: 'pending' },
          { label: t('adminDashboard.privateGroups.tabs.active', 'نشطة'), value: metrics.active, cls: 'text-brand-600 dark:text-brand-400', tab: 'active' },
          { label: t('adminDashboard.privateGroups.tabs.stopped', 'متوقفة'), value: metrics.stopped, cls: 'text-red-500 dark:text-red-400', tab: 'stopped' },
          { label: t('adminDashboard.privateGroups.tabs.completed', 'مكتملة'), value: metrics.completed, cls: 'text-slate-500 dark:text-slate-400', tab: 'completed' },
        ].map((m) => (
          <button
            key={m.tab}
            type="button"
            onClick={() => handleTabChange(m.tab)}
            className={`flex flex-col items-center justify-center gap-1 p-5 rounded-3xl border shadow-soft transition-all cursor-pointer ${
              activeTab === m.tab
                ? 'bg-brand-50 dark:bg-brand-900/20 border-brand-300 dark:border-brand-700'
                : 'bg-white dark:bg-slate-900 border-slate-100 dark:border-slate-800/60 hover:border-brand-200 dark:hover:border-brand-800'
            }`}
          >
            <span className={`text-3xl font-extrabold ${m.cls}`}>{m.value}</span>
            <span className="text-xs font-semibold text-slate-400 dark:text-slate-500 text-center">{m.label}</span>
          </button>
        ))}
      </div>

      <div className="flex flex-col gap-3 p-4 bg-white dark:bg-slate-900 rounded-3xl border border-slate-100 dark:border-slate-800/60 shadow-soft">
        <div className="flex flex-col sm:flex-row items-stretch sm:items-center justify-between gap-3">
          <div className="flex items-center gap-3 flex-wrap">
            <button
              onClick={() => {
                setSelectedGroup(null)
                setViewMode('add-group')
              }}
              className="flex items-center gap-2 px-5 py-2.5 rounded-2xl bg-brand-500 hover:bg-brand-600 text-white text-sm font-semibold transition-all shadow-md shadow-brand-500/20 active:scale-[0.98] cursor-pointer"
            >
              <Plus size={18} />
              <span>{t('adminDashboard.groups.addGroup', 'إضافة مجموعة')}</span>
            </button>

            <div className="flex items-center gap-1.5 flex-wrap">
              {TYPE_FILTER_VALUES.map((typeVal) => (
                <button
                  key={typeVal}
                  onClick={() => handleTypeChange(typeVal)}
                  className={`px-3 py-1.5 rounded-xl text-xs font-bold transition-all cursor-pointer ${
                    typeFilter === typeVal
                      ? 'bg-brand-500 text-white shadow-sm'
                      : 'bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-700'
                  }`}
                >
                  {TYPE_LABELS[typeVal]}
                </button>
              ))}
            </div>
          </div>

          <div className="relative w-full sm:w-64">
            <Search
              size={16}
              className={`absolute ${isRtl ? 'right-3' : 'left-3'} top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none`}
            />
            <input
              type="text"
              placeholder={t('adminDashboard.groups.searchPlaceholder', 'بحث في المجموعات...')}
              value={searchQuery}
              onChange={(e) => {
                setSearchQuery(e.target.value)
                setCurrentPage(1)
              }}
              className={`w-full bg-[#f3f7f6] dark:bg-slate-800 rounded-2xl py-2.5 ${isRtl ? 'pr-9 pl-4' : 'pl-9 pr-4'} text-sm text-slate-700 dark:text-slate-200 outline-none border border-transparent focus:border-brand-400 transition-colors placeholder-slate-400`}
            />
          </div>
        </div>

        <div className="flex items-center gap-1.5 flex-wrap border-t border-slate-100 dark:border-slate-800 pt-3">
          {STATUS_TABS.map((tab) => (
            <button
              key={tab.key}
              onClick={() => handleTabChange(tab.key)}
              className={`px-4 py-1.5 rounded-xl text-xs font-bold transition-all cursor-pointer ${
                activeTab === tab.key
                  ? 'bg-brand-500 text-white shadow-sm'
                  : 'bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-700'
              }`}
            >
              {tab.label}
            </button>
          ))}
        </div>
      </div>

      {groups.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-20 gap-3 text-slate-400 bg-white dark:bg-slate-900 rounded-3xl border border-slate-100 dark:border-slate-800/60">
          <Layers size={48} strokeWidth={1.5} />
          <p className="text-sm font-medium">{t('adminDashboard.groups.noGroupsFound', 'لا توجد مجموعات مطابقة')}</p>
        </div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-5">
          {groups.map((group) => (
            <GroupCard
              key={group.id}
              group={group}
              onEdit={handleEditGroup}
              onViewStudents={handleViewStudents}
              onDelete={handleDeleteGroup}
              onChangeTeacher={handleOpenChangeTeacher}
              t={t}
              isRtl={isRtl}
            />
          ))}
        </div>
      )}

      <div
        className={`flex flex-col sm:flex-row items-center justify-between gap-4 p-5 bg-white dark:bg-slate-900 border border-slate-100 dark:border-slate-800 rounded-3xl shadow-soft mt-6 transition-opacity duration-300 ${
          isPaginationDimmed ? 'opacity-40 pointer-events-none select-none' : ''
        }`}
      >
        <div className="text-sm text-slate-400 dark:text-slate-500 font-medium">
          {isRtl ? (
            <>
              {t('adminDashboard.students.pagination.showing', 'عرض')}{' '}
              <span className="font-semibold text-slate-700 dark:text-slate-200">{startIdx}</span>{' '}
              {t('adminDashboard.students.pagination.to', 'إلى')}{' '}
              <span className="font-semibold text-slate-700 dark:text-slate-200">{endIdx}</span>{' '}
              {t('adminDashboard.students.pagination.of', 'من أصل')}{' '}
              <span className="font-semibold text-slate-700 dark:text-slate-200">{totalCount}</span>{' '}
              {t('adminDashboard.privateGroups.title', 'مجموعة')}
            </>
          ) : (
            <>
              {t('adminDashboard.students.pagination.showing', 'Showing')}{' '}
              <span className="font-semibold text-slate-700 dark:text-slate-200">{startIdx}</span>{' '}
              {t('adminDashboard.students.pagination.to', 'to')}{' '}
              <span className="font-semibold text-slate-700 dark:text-slate-200">{endIdx}</span>{' '}
              {t('adminDashboard.students.pagination.of', 'of')}{' '}
              <span className="font-semibold text-slate-700 dark:text-slate-200">{totalCount}</span>{' '}
              {t('adminDashboard.privateGroups.title', 'groups')}
            </>
          )}
        </div>

        <div className="flex items-center gap-2">
          <button
            type="button"
            onClick={() => setCurrentPage((prev) => Math.max(prev - 1, 1))}
            disabled={currentPage === 1 || isPaginationDimmed}
            className="flex items-center gap-1.5 px-4 py-2 rounded-xl text-xs sm:text-sm font-semibold border border-slate-100 dark:border-slate-800 bg-white hover:bg-slate-50 dark:bg-slate-900 dark:hover:bg-slate-800 text-slate-700 dark:text-slate-300 disabled:opacity-40 disabled:cursor-not-allowed transition-all cursor-pointer"
          >
            {isRtl ? <ChevronRight size={16} aria-hidden="true" /> : <ChevronLeft size={16} aria-hidden="true" />}
          </button>
          <span className="px-3 py-2 rounded-xl text-xs sm:text-sm font-bold border border-slate-100 dark:border-slate-800 bg-white dark:bg-slate-900 text-slate-700 dark:text-slate-300 min-w-[80px] text-center">
            {currentPage} / {totalPages}
          </span>
          <button
            type="button"
            onClick={() => setCurrentPage((prev) => Math.min(prev + 1, totalPages))}
            disabled={currentPage === totalPages || isPaginationDimmed}
            className="flex items-center gap-1.5 px-4 py-2 rounded-xl text-xs sm:text-sm font-semibold border border-slate-100 dark:border-slate-800 bg-white hover:bg-slate-50 dark:bg-slate-900 dark:hover:bg-slate-800 text-slate-700 dark:text-slate-300 disabled:opacity-40 disabled:cursor-not-allowed transition-all cursor-pointer"
          >
            {isRtl ? <ChevronLeft size={16} aria-hidden="true" /> : <ChevronRight size={16} aria-hidden="true" />}
          </button>
        </div>
      </div>

      {showStudentsModal && selectedGroup && (
        <GroupDetailsModal
          group={selectedGroup}
          onClose={() => {
            setShowStudentsModal(false)
            setSelectedGroup(null)
          }}
          onRemoveStudent={handleRemoveStudent}
          onOpenAddStudents={() => {
            setShowStudentsModal(false)
            setShowAddStudentsModal(true)
          }}
          onAddStudent={handleAddSingleStudent}
          onChangeTeacher={handleOpenChangeTeacher}
          t={t}
          isRtl={isRtl}
        />
      )}

      {showAddStudentsModal && selectedGroup && (
        <AddStudentsModal
          group={selectedGroup}
          isRtl={isRtl}
          onAdd={handleAddStudents}
          onCancel={() => setShowAddStudentsModal(false)}
        />
      )}

      {showChangeTeacherModal && groupForTeacherChange && (
        <ChangeTeacherModal
          group={groupForTeacherChange}
          onClose={() => {
            setShowChangeTeacherModal(false)
            setGroupForTeacherChange(null)
          }}
          onConfirm={handleChangeTeacher}
          isRtl={isRtl}
        />
      )}
    </div>
  )
}

import React, { useState, useRef, useEffect } from 'react'
import { useTranslation } from 'react-i18next'
import { ArrowRight, ArrowLeft, Loader2 } from 'lucide-react'
import { showErrorToast } from '@/shared/utils/sweetAlert'
import { landingApi } from '@/shared/services/api/landingApi'
import { adminCurriculaApi } from '@/shared/services/api/adminCurriculaApi'
import { adminLevelsApi } from '@/shared/services/api/adminLevelsApi'
import { teachersApi } from '@/shared/services/api/teachersApi'
import { explanationLanguagesApi } from '@/shared/services/api/explanationLanguagesApi'
import { normalizeCountries } from '@/shared/utils/countryUtils'
import GroupInfoCard from './GroupInfoCard'
import GroupScheduleCard from './GroupScheduleCard'

class SafeErrorBoundary extends React.Component {
  constructor(props) {
    super(props)
    this.state = { hasError: false }
  }

  static getDerivedStateFromError() {
    return { hasError: true }
  }

  componentDidCatch(error, errorInfo) {
    console.error('SafeErrorBoundary caught group error:', error, errorInfo)
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="p-8 bg-white dark:bg-slate-900 rounded-3xl border border-rose-200 dark:border-rose-900/40 text-center space-y-4">
          <p className="text-sm font-bold text-rose-600 dark:text-rose-400">
            حدث خطأ أثناء عرض بيانات المجموعة
          </p>
          <button
            type="button"
            onClick={this.props.onCancel}
            className="px-5 py-2.5 bg-brand-500 hover:bg-brand-600 text-white text-xs font-bold rounded-2xl transition-all cursor-pointer shadow-md shadow-brand-500/20"
          >
            العودة إلى قائمة المجموعات
          </button>
        </div>
      )
    }
    return this.props.children
  }
}

const resolveEntityId = (val) => {
  if (val === null || val === undefined) return ''
  if (typeof val === 'string' || typeof val === 'number') return String(val)
  if (typeof val === 'object') {
    return String(val.id || val._id || val.teacher_id || val.user_id || val.code || val.value || '')
  }
  return ''
}

const safeExtractDateString = (val) => {
  if (!val) return ''
  if (typeof val === 'string') {
    const clean = val.includes('T') ? val.split('T')[0] : val.trim()
    return clean.length >= 8 ? clean : ''
  }
  if (typeof val === 'number' || val instanceof Date) {
    try {
      return new Date(val).toISOString().split('T')[0]
    } catch {
      return ''
    }
  }
  return ''
}

const safeExtractName = (nameVal, lang = 'ar') => {
  if (!nameVal) return ''
  if (typeof nameVal === 'string') return nameVal
  if (typeof nameVal === 'object') {
    return nameVal[lang] || nameVal.ar || nameVal.en || ''
  }
  return String(nameVal)
}

const normalizeScheduleList = (rawList) => {
  if (!Array.isArray(rawList) || rawList.length === 0) {
    return [
      { day: 'sunday', startTime: '16:00', endTime: '17:30' },
      { day: 'tuesday', startTime: '16:00', endTime: '17:30' },
    ]
  }

  const result = rawList.map((s) => {
    if (!s) return null
    let day = 'sunday'
    if (typeof s.day === 'object' && s.day !== null) {
      day = (s.day.key || s.day.en || s.day.ar || 'sunday').toString().toLowerCase()
    } else if (typeof s.day === 'string' && s.day.trim()) {
      day = s.day.trim().toLowerCase()
    }
    const startTime = typeof s.startTime === 'string' ? s.startTime : (s.timeFrom || '16:00')
    const endTime = typeof s.endTime === 'string' ? s.endTime : (s.timeTo || '17:30')
    return { day, startTime, endTime }
  }).filter(Boolean)

  return result.length > 0 ? result : [
    { day: 'sunday', startTime: '16:00', endTime: '17:30' },
    { day: 'tuesday', startTime: '16:00', endTime: '17:30' },
  ]
}

function AddEditGroupScreenContent({ group = null, isRtl, isSaving = false, onSave, onCancel }) {
  const { t, i18n } = useTranslation()
  const isRtlResolved = isRtl !== undefined ? isRtl : i18n.language.startsWith('ar')
  const BackArrow = isRtlResolved ? ArrowRight : ArrowLeft
  const fileInputRef = useRef(null)

  const [formData, setFormData] = useState({
    name: safeExtractName(group?.name, 'ar'),
    nameAr: safeExtractName(group?.name, 'ar') || safeExtractName(group?.nameAr, 'ar'),
    nameEn: safeExtractName(group?.name, 'en') || safeExtractName(group?.nameEn, 'en'),
    country: resolveEntityId(group?.country),
    curriculum: resolveEntityId(group?.curriculum),
    studentLevel: resolveEntityId(group?.studentLevel),
    teacher: resolveEntityId(group?.teacher),
    type: group?.type || 'group',
    language: group?.language || 'العربية',
    maxStudents: group?.maxStudents || 5,
    status: group?.status || 'active',
    startDate: safeExtractDateString(group?.startDate),
    endDate: safeExtractDateString(group?.endDate),
    image: group?.image || null,
  })

  const [schedule, setSchedule] = useState(() => {
    return normalizeScheduleList(group?.weeklySchedule || group?.schedule)
  })

  useEffect(() => {
    if (group) {
      setFormData({
        name: safeExtractName(group.name, 'ar'),
        nameAr: safeExtractName(group.name, 'ar') || safeExtractName(group.nameAr, 'ar'),
        nameEn: safeExtractName(group.name, 'en') || safeExtractName(group.nameEn, 'en'),
        country: resolveEntityId(group.country),
        curriculum: resolveEntityId(group.curriculum),
        studentLevel: resolveEntityId(group.studentLevel),
        teacher: resolveEntityId(group.teacher),
        type: group.type || 'group',
        language: group.language || 'العربية',
        maxStudents: group.maxStudents || 5,
        status: group.status || 'active',
        startDate: safeExtractDateString(group.startDate),
        endDate: safeExtractDateString(group.endDate),
        image: group.image || null,
      })
      setSchedule(normalizeScheduleList(group.weeklySchedule || group.schedule))
    }
  }, [group])

  const [newDay, setNewDay] = useState('sunday')
  const [newTimeFrom, setNewTimeFrom] = useState('16:00')
  const [newTimeTo, setNewTimeTo] = useState('17:30')
  const [errors, setErrors] = useState({})

  const [countries, setCountries] = useState([])
  const [curricula, setCurricula] = useState([])
  const [levels, setLevels] = useState([])
  const [teachers, setTeachers] = useState([])
  const [languages, setLanguages] = useState([])

  useEffect(() => {
    let isMounted = true
    const loadSelectOptions = async () => {
      try {
        const [cRes, curRes, lvlRes, tRes, langRes] = await Promise.allSettled([
          landingApi.fetchCountries(),
          adminCurriculaApi.fetchCurricula(),
          adminLevelsApi.fetchLevels(),
          teachersApi.fetchTeachers({ limit: 100 }),
          explanationLanguagesApi.fetchLanguages(),
        ])

        if (!isMounted) return

        if (cRes.status === 'fulfilled' && cRes.value) {
          const rawList = cRes.value?.data || (Array.isArray(cRes.value) ? cRes.value : [])
          const list = normalizeCountries(rawList)
          if (Array.isArray(list) && list.length > 0) setCountries(list)
        }
        if (curRes.status === 'fulfilled' && curRes.value) {
          const list = curRes.value?.data || (Array.isArray(curRes.value) ? curRes.value : [])
          if (Array.isArray(list) && list.length > 0) setCurricula(list)
        }
        if (lvlRes.status === 'fulfilled' && lvlRes.value) {
          const list = lvlRes.value?.data || (Array.isArray(lvlRes.value) ? lvlRes.value : [])
          if (Array.isArray(list) && list.length > 0) setLevels(list)
        }
        if (tRes.status === 'fulfilled' && tRes.value) {
          const list = tRes.value?.data || (Array.isArray(tRes.value) ? tRes.value : [])
          if (Array.isArray(list) && list.length > 0) setTeachers(list)
        }
        if (langRes.status === 'fulfilled' && langRes.value) {
          const list = langRes.value?.data || (Array.isArray(langRes.value) ? langRes.value : [])
          if (Array.isArray(list) && list.length > 0) setLanguages(list)
        }
      } catch (err) {
        console.warn('Could not load options for group form:', err)
      }
    }

    loadSelectOptions()
    return () => {
      isMounted = false
    }
  }, [])

  const handleChange = (key, value) => {
    setFormData((prev) => ({ ...prev, [key]: value }))
    if (errors[key]) {
      setErrors((prev) => {
        const next = { ...prev }
        delete next[key]
        return next
      })
    }
  }

  const handleImageSelect = (e) => {
    const file = e.target.files[0]
    if (!file) return
    const reader = new FileReader()
    reader.onloadend = () => handleChange('image', reader.result)
    reader.readAsDataURL(file)
  }

  const handleAddSchedule = () => {
    const exists = schedule.find((s) => s.day === newDay && s.startTime === newTimeFrom)
    if (exists) return
    setSchedule((prev) => [...prev, { day: newDay, startTime: newTimeFrom, endTime: newTimeTo }])
    if (errors.schedule) {
      setErrors((prev) => {
        const next = { ...prev }
        delete next.schedule
        return next
      })
    }
  }

  const handleRemoveSchedule = (day, index) => {
    setSchedule((prev) => prev.filter((_, idx) => idx !== index))
  }

  const handleSave = (e) => {
    e.preventDefault()
    const newErrors = {}
    const nameAr = (formData.nameAr || formData.name || '').trim()
    const nameEn = (formData.nameEn || '').trim()

    if (!nameAr) {
      newErrors.nameAr = t('adminDashboard.groups.enterGroupNameArError', 'الرجاء إدخال اسم المجموعة باللغة العربية!')
    }
    if (!nameEn) {
      newErrors.nameEn = t('adminDashboard.groups.enterGroupNameEnError', 'الرجاء إدخال اسم المجموعة باللغة الإنجليزية!')
    }

    if (!formData.country) {
      newErrors.country = t('adminDashboard.groups.selectCountryError', 'الرجاء اختيار الدولة!')
    }
    if (!formData.curriculum) {
      newErrors.curriculum = t('adminDashboard.groups.selectCurriculumError', 'الرجاء اختيار المنهج الدراسي!')
    }
    if (!formData.studentLevel) {
      newErrors.studentLevel = t('adminDashboard.groups.selectLevelError', 'الرجاء اختيار المستوى الدراسي!')
    }
    if (!formData.teacher) {
      newErrors.teacher = t('adminDashboard.groups.selectTeacherError', 'الرجاء اختيار المعلم!')
    }

    const maxStudentsNum = Number(formData.maxStudents)
    if (!formData.maxStudents || isNaN(maxStudentsNum) || maxStudentsNum < 1) {
      newErrors.maxStudents = t('adminDashboard.groups.maxStudentsError', 'الحد الأقصى للطلاب يجب أن يكون 1 على الأقل!')
    }

    if (formData.startDate && formData.endDate && new Date(formData.startDate) > new Date(formData.endDate)) {
      newErrors.endDate = t('adminDashboard.groups.dateOrderError', 'تاريخ الانتهاء يجب أن يكون بعد تاريخ البدء!')
    }

    if (!schedule || schedule.length === 0) {
      newErrors.schedule = t('adminDashboard.groups.scheduleEmptyError', 'الرجاء إضافة موعد واحد على الأقل في الجدول الأسبوعي!')
    } else {
      const invalidSlot = schedule.find((s) => !s.day || !s.startTime || !s.endTime)
      if (invalidSlot) {
        newErrors.schedule = t('adminDashboard.groups.scheduleInvalidError', 'الرجاء التأكد من صحة أوقات الحصص!')
      } else {
        const orderInvalid = schedule.find((s) => s.startTime >= s.endTime)
        if (orderInvalid) {
          newErrors.schedule = t('adminDashboard.groups.scheduleTimeOrderError', 'وقت بداية الحصة يجب أن يكون قبل وقت نهايتها!')
        }
      }
    }

    setErrors(newErrors)

    const firstError = Object.values(newErrors)[0]
    if (firstError) {
      showErrorToast(firstError, isRtlResolved)
      return
    }

    const payload = {
      name: {
        ar: nameAr,
        en: nameEn,
      },
      country: formData.country,
      curriculum: formData.curriculum,
      studentLevel: formData.studentLevel,
      type: formData.type || 'group',
      language: formData.language || 'العربية',
      maxStudents: maxStudentsNum || 1,
      teacher: formData.teacher,
      weeklySchedule: schedule.map((s) => ({
        day: (s.day || '').toLowerCase(),
        startTime: s.startTime || s.timeFrom || '16:00',
        endTime: s.endTime || s.timeTo || '17:30',
      })),
      ...(formData.startDate ? { startDate: formData.startDate } : {}),
      ...(formData.endDate ? { endDate: formData.endDate } : {}),
      ...(group && { status: formData.status || 'active' }),
    }

    onSave(payload)
  }

  return (
    <div className="space-y-6" dir={isRtlResolved ? 'rtl' : 'ltr'}>
      <div className="flex items-center justify-between">
        <button
          type="button"
          onClick={onCancel}
          className="flex items-center gap-2 text-slate-500 hover:text-slate-800 dark:hover:text-white transition-colors cursor-pointer text-sm font-semibold"
        >
          <BackArrow size={18} />
          <span>{t('common.cancel', 'إلغاء')}</span>
        </button>

        <h2 className="text-xl font-bold text-slate-800 dark:text-white">
          {group
            ? t('adminDashboard.groups.editDetails', 'تعديل بيانات المجموعة')
            : t('adminDashboard.groups.createNewGroup', 'إنشاء مجموعة جديدة')}
        </h2>

        <div className="w-16" />
      </div>

      <form onSubmit={handleSave} className="space-y-6">
        <GroupInfoCard
          formData={formData}
          handleChange={handleChange}
          handleImageSelect={handleImageSelect}
          fileInputRef={fileInputRef}
          countries={countries}
          curricula={curricula}
          levels={levels}
          teachers={teachers}
          languages={languages}
          isRtl={isRtlResolved}
          t={t}
          isEditing={Boolean(group)}
          errors={errors}
        />

        <GroupScheduleCard
          schedule={schedule}
          newDay={newDay}
          setNewDay={setNewDay}
          newTimeFrom={newTimeFrom}
          setNewTimeFrom={setNewTimeFrom}
          newTimeTo={newTimeTo}
          setNewTimeTo={setNewTimeTo}
          handleAddSchedule={handleAddSchedule}
          handleRemoveSchedule={handleRemoveSchedule}
          t={t}
          isRtl={isRtlResolved}
          error={errors.schedule}
        />

        <div className="flex items-center justify-end gap-3 pt-2">
          <button
            type="button"
            onClick={onCancel}
            disabled={isSaving}
            className="px-6 py-3 rounded-2xl border border-slate-200 dark:border-slate-800 text-slate-600 dark:text-slate-300 hover:bg-slate-50 dark:hover:bg-slate-800 text-sm font-semibold transition-all cursor-pointer disabled:opacity-50"
          >
            {t('common.cancel', 'إلغاء')}
          </button>
          <button
            type="submit"
            disabled={isSaving}
            className="px-8 py-3 rounded-2xl bg-brand-500 hover:bg-brand-600 text-white text-sm font-bold shadow-lg shadow-brand-500/20 active:scale-95 transition-all cursor-pointer flex items-center justify-center gap-2 disabled:opacity-50"
          >
            {isSaving && <Loader2 className="w-4 h-4 animate-spin" />}
            {group
              ? t('adminDashboard.groups.saveChanges', 'حفظ التعديلات')
              : t('adminDashboard.groups.createButton', 'إنشاء المجموعة')}
          </button>
        </div>
      </form>
    </div>
  )
}

export default function AddEditGroupScreen(props) {
  return (
    <SafeErrorBoundary onCancel={props.onCancel}>
      <AddEditGroupScreenContent {...props} />
    </SafeErrorBoundary>
  )
}

import { useState, useRef, useEffect, useMemo } from 'react'
import { ChevronDown, Search, X, Check, User, Loader2 } from 'lucide-react'
import { studentsApi } from '@/shared/services/api/studentsApi'

export default function StudentSelect({
  students = [],
  selectedStudent = null,
  onSelect,
  excludeIds = [],
  placeholder = 'اختر طالباً...',
  isRtl = true,
  disabled = false,
}) {
  const [isOpen, setIsOpen] = useState(false)
  const [searchQuery, setSearchQuery] = useState('')
  const [isSearching, setIsSearching] = useState(false)
  const [backendStudents, setBackendStudents] = useState(null)
  const containerRef = useRef(null)
  const searchInputRef = useRef(null)

  const excludedSet = useMemo(() => new Set(excludeIds.map(String)), [excludeIds])

  const currentPool = useMemo(() => {
    const list = backendStudents !== null ? backendStudents : students
    return Array.isArray(list) ? list : []
  }, [backendStudents, students])

  const availableStudents = useMemo(() => {
    return currentPool.filter((s) => !excludedSet.has(String(s.id || s._id)))
  }, [currentPool, excludedSet])

  useEffect(() => {
    if (!isOpen) return

    const trimmed = searchQuery.trim()
    if (!trimmed) {
      setBackendStudents(null)
      setIsSearching(false)
      return
    }

    let active = true
    setIsSearching(true)

    const timer = setTimeout(async () => {
      try {
        const res = await studentsApi.fetchStudents({ search: trimmed, limit: 50 })
        if (!active) return
        const list = res?.data || (Array.isArray(res) ? res : [])
        setBackendStudents(Array.isArray(list) ? list : [])
      } catch (err) {
        console.warn('Backend student search failed:', err)
        if (active) setBackendStudents([])
      } finally {
        if (active) setIsSearching(false)
      }
    }, 350)

    return () => {
      active = false
      clearTimeout(timer)
    }
  }, [searchQuery, isOpen])

  useEffect(() => {
    const handleClickOutside = (e) => {
      if (containerRef.current && !containerRef.current.contains(e.target)) {
        setIsOpen(false)
      }
    }
    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [])

  useEffect(() => {
    if (isOpen && searchInputRef.current) {
      searchInputRef.current.focus()
    }
  }, [isOpen])

  const getStudentName = (s) => {
    if (!s) return ''
    if (typeof s.name === 'object' && s.name !== null) {
      return isRtl ? (s.name.ar || s.name.en) : (s.name.en || s.name.ar)
    }
    return s.name || ''
  }

  const selectedName = selectedStudent ? getStudentName(selectedStudent) : ''

  return (
    <div className="relative w-full" ref={containerRef} dir={isRtl ? 'rtl' : 'ltr'}>
      <button
        type="button"
        disabled={disabled}
        onClick={() => setIsOpen((prev) => !prev)}
        className={`w-full flex items-center justify-between gap-3 bg-[#f3f7f6] dark:bg-slate-950 border ${
          isOpen ? 'border-brand-500 shadow-sm' : 'border-slate-200 dark:border-slate-800'
        } rounded-2xl py-3 px-4 text-sm text-slate-800 dark:text-slate-100 transition-all hover:bg-slate-100 dark:hover:bg-slate-900 cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed`}
      >
        <div className="flex items-center gap-2.5 min-w-0">
          <div className="w-7 h-7 rounded-xl bg-brand-50 dark:bg-brand-900/30 text-brand-600 dark:text-brand-400 flex items-center justify-center shrink-0 text-xs font-bold">
            {selectedStudent ? (selectedName.charAt(0) || <User size={14} />) : <User size={14} />}
          </div>
          <span className={`truncate font-medium ${selectedStudent ? 'text-slate-800 dark:text-slate-100' : 'text-slate-400'}`}>
            {selectedStudent ? selectedName : placeholder}
          </span>
        </div>
        <div className="flex items-center gap-1.5 shrink-0 text-slate-400">
          {selectedStudent && (
            <span
              onClick={(e) => {
                e.stopPropagation()
                onSelect(null)
              }}
              className="p-1 hover:text-red-500 rounded-md transition-colors"
              title="إلغاء التحديد"
            >
              <X size={14} />
            </span>
          )}
          <ChevronDown
            size={16}
            className={`transition-transform duration-200 ${isOpen ? 'rotate-180' : ''}`}
          />
        </div>
      </button>

      {isOpen && (
        <div className="absolute left-0 right-0 top-full mt-2 z-50 bg-white dark:bg-slate-900 rounded-3xl shadow-2xl border border-slate-100 dark:border-slate-800 p-3 space-y-2 max-h-80 flex flex-col animate-fadeIn">
          <div className="relative shrink-0">
            {isSearching ? (
              <Loader2 size={14} className={`absolute ${isRtl ? 'right-3' : 'left-3'} top-1/2 -translate-y-1/2 text-brand-500 animate-spin pointer-events-none`} />
            ) : (
              <Search size={14} className={`absolute ${isRtl ? 'right-3' : 'left-3'} top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none`} />
            )}
            <input
              ref={searchInputRef}
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder={isRtl ? 'ابحث في الطلاب (بحث من السيرفر)...' : 'Search students (server search)...'}
              className={`w-full bg-[#f3f7f6] dark:bg-slate-800 rounded-xl py-2 ${
                isRtl ? 'pr-9 pl-8' : 'pl-9 pr-8'
              } text-xs text-slate-800 dark:text-slate-100 outline-none border border-transparent focus:border-brand-400 transition-colors`}
            />
            {searchQuery && (
              <button
                type="button"
                onClick={() => {
                  setSearchQuery('')
                  setBackendStudents(null)
                }}
                className={`absolute ${isRtl ? 'left-2.5' : 'right-2.5'} top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600 p-0.5 cursor-pointer`}
              >
                <X size={12} />
              </button>
            )}
          </div>

          <div className="overflow-y-auto space-y-1 pr-0.5 max-h-56 pb-6 overscroll-contain">
            {isSearching ? (
              <div className="py-6 flex flex-col items-center justify-center gap-2 text-xs text-slate-400">
                <Loader2 size={16} className="animate-spin text-brand-500" />
                <span>{isRtl ? 'جاري البحث في قاعدة البيانات...' : 'Searching database...'}</span>
              </div>
            ) : availableStudents.length === 0 ? (
              <div className="py-6 text-center text-xs text-slate-400">
                {isRtl ? 'لا يوجد طلاب متاحون' : 'No students found'}
              </div>
            ) : (
              availableStudents.map((student) => {
                const sId = student.id || student._id
                const sName = getStudentName(student)
                const isSelected = selectedStudent && String(selectedStudent.id || selectedStudent._id) === String(sId)

                return (
                  <button
                    key={sId}
                    type="button"
                    onClick={() => {
                      onSelect(student)
                      setIsOpen(false)
                      setSearchQuery('')
                      setBackendStudents(null)
                    }}
                    className={`w-full flex items-center justify-between p-2.5 rounded-2xl text-start transition-all cursor-pointer ${
                      isSelected
                        ? 'bg-brand-500 text-white font-semibold shadow-sm'
                        : 'hover:bg-slate-50 dark:hover:bg-slate-800/70 text-slate-700 dark:text-slate-200'
                    }`}
                  >
                    <div className="flex items-center gap-2.5 min-w-0">
                      <div
                        className={`w-8 h-8 rounded-xl flex items-center justify-center font-bold text-xs shrink-0 ${
                          isSelected
                            ? 'bg-white/20 text-white'
                            : 'bg-brand-50 dark:bg-brand-900/30 text-brand-600 dark:text-brand-400'
                        }`}
                      >
                        {student.image || student.avatar ? (
                          <img src={student.image || student.avatar} alt="" className="w-full h-full rounded-xl object-cover" />
                        ) : (
                          sName.charAt(0) || <User size={14} />
                        )}
                      </div>
                      <div className="min-w-0">
                        <p className={`text-xs font-bold truncate ${isSelected ? 'text-white' : 'text-slate-800 dark:text-slate-100'}`}>
                          {sName}
                        </p>
                        {(student.email || student.phone) && (
                          <p className={`text-[10px] truncate ${isSelected ? 'text-white/80' : 'text-slate-400'}`}>
                            {student.email || student.phone}
                          </p>
                        )}
                      </div>
                    </div>
                    {isSelected && <Check size={16} className="text-white shrink-0" />}
                  </button>
                )
              })
            )}
          </div>
        </div>
      )}
    </div>
  )
}

import { useState, useEffect } from 'react'
import { useTranslation } from 'react-i18next'
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query'
import { toast } from 'react-hot-toast'
import { Plus } from 'lucide-react'

import { adminLevelsApi } from '@/shared/services/api/adminLevelsApi'
import Spinner from '@/shared/components/Spinner'

import StudentLevelForm from './components/StudentLevelForm'
import StudentLevelCard from './components/StudentLevelCard'
import { showDeleteConfirm } from '@/shared/utils/sweetAlert'

export default function AdminStudentLevels() {
  const { i18n } = useTranslation()
  const isRtl = i18n.language.startsWith('ar')
  const queryClient = useQueryClient()

  const [levels, setLevels] = useState([])

  const { data: levelsData, isLoading: isLoadingLevels } = useQuery({
    queryKey: ['student-levels', i18n.language],
    queryFn: () => adminLevelsApi.fetchLevels(),
    staleTime: 5 * 60 * 1000,
  })

  useEffect(() => {
    const rawData = levelsData?.data || (Array.isArray(levelsData) ? levelsData : [])
    if (rawData) {
      const fetchedLevels = rawData.map((item) => ({
        id: item.id || item._id,
        name: typeof item.name === 'object' ? (item.name.ar || item.name.en || '') : item.name,
        nameEn: typeof item.name === 'object' ? (item.name.en || item.name.ar || '') : (item.nameEn || item.name || ''),
        createdAt: item.createdAt,
      }))
      setLevels(fetchedLevels)
    }
  }, [levelsData, i18n.language])

  const [showForm, setShowForm] = useState(false)
  const [editingLevelId, setEditingLevelId] = useState(null)
  const [levelNameAr, setLevelNameAr] = useState('')
  const [levelNameEn, setLevelNameEn] = useState('')

  const createMutation = useMutation({
    mutationFn: adminLevelsApi.createLevel,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['student-levels'] })
      setShowForm(false)
      setLevelNameAr('')
      setLevelNameEn('')
      toast.success(isRtl ? 'تم إضافة المستوى بنجاح!' : 'Level added successfully!')
    },
    onError: (err) => {
      console.error('Failed to create level', err)
      toast.error(isRtl ? 'حدث خطأ أثناء إضافة المستوى' : 'Failed to add level')
    }
  })

  const updateMutation = useMutation({
    mutationFn: ({ id, payload }) => adminLevelsApi.updateLevel(id, payload),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['student-levels'] })
      setEditingLevelId(null)
      setShowForm(false)
      setLevelNameAr('')
      setLevelNameEn('')
      toast.success(isRtl ? 'تم تحديث المستوى بنجاح!' : 'Level updated successfully!')
    },
    onError: (err) => {
      console.error('Failed to update level', err)
      toast.error(isRtl ? 'حدث خطأ أثناء تعديل المستوى' : 'Failed to edit level')
    }
  })

  const deleteMutation = useMutation({
    mutationFn: (id) => adminLevelsApi.deleteLevel(id),
    onSuccess: () => {
      queryClient.invalidateQueries(['student-levels'])
      toast.success(isRtl ? 'تم حذف المستوى بنجاح!' : 'Level deleted successfully!')
    },
    onError: (err) => {
      console.error('Failed to delete level', err)
      toast.error(isRtl ? 'حدث خطأ أثناء حذف المستوى' : 'Failed to delete level')
    }
  })

  const handleSaveLevel = async (e) => {
    e.preventDefault()
    if (!levelNameAr.trim() || !levelNameEn.trim()) {
      toast.error(isRtl ? 'الرجاء إدخال الاسم باللغتين العربية والإنجليزية!' : 'Please enter the name in both Arabic and English!')
      return
    }

    const payload = {
      name: {
        ar: levelNameAr.trim(),
        en: levelNameEn.trim()
      }
    }

    if (editingLevelId) {
      await updateMutation.mutateAsync({ id: editingLevelId, payload })
    } else {
      await createMutation.mutateAsync(payload)
    }
  }

  const handleEditLevelClick = async (lvl) => {
    try {
      const res = await adminLevelsApi.fetchLevelById(lvl.id);
      const lvlData = res?.data || res;
      setShowForm(false)
      setEditingLevelId(lvl.id);
      setLevelNameAr(lvlData.name?.ar || lvlData.name || '');
      setLevelNameEn(lvlData.name?.en || lvlData.nameEn || lvlData.name || '');
      setShowForm(true);
    } catch (error) {
      console.error('Failed to fetch level details for edit:', error);
      toast.error(isRtl ? 'حدث خطأ أثناء تحميل بيانات المستوى' : 'Failed to load level details');
    }
  }

  const handleDeleteLevel = async (level) => {
    const isConfirmed = await showDeleteConfirm(isRtl, level.name);
    if (!isConfirmed) return;
    await deleteMutation.mutateAsync(level.id);
  }

  if (isLoadingLevels) {
    return (
      <div className="flex h-[60vh] items-center justify-center">
        <Spinner />
      </div>
    )
  }

  return (
    <div className="space-y-8 p-1 md:p-6 text-start animate-fadeIn" dir={isRtl ? 'rtl' : 'ltr'}>

      <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-slate-800 dark:text-white">
            {isRtl ? 'مستويات الطلاب' : 'Student Levels'}
          </h1>
          <p className="text-sm text-slate-400 dark:text-slate-500 mt-1">
            {isRtl ? 'منارة العز أكاديمي · لوحة الإدارة' : 'Ezz Academy · Admin Dashboard'}
          </p>
        </div>

        <button
          type="button"
          onClick={() => {
            setShowForm(!showForm)
            setEditingLevelId(null)
            setLevelNameAr('')
            setLevelNameEn('')
          }}
          className="px-5 py-3 bg-[#005953] hover:bg-[#004742] text-white rounded-2xl text-sm font-semibold transition-all shadow-md flex items-center gap-2 cursor-pointer self-start sm:self-center hover:scale-102 active:scale-95"
        >
          <Plus size={16} />
          <span>{isRtl ? 'إضافة مستوى' : 'Add Level'}</span>
        </button>
      </div>

      {showForm && (
        <StudentLevelForm
          key={editingLevelId || 'new'}
          levelNameAr={levelNameAr}
          setLevelNameAr={setLevelNameAr}
          levelNameEn={levelNameEn}
          setLevelNameEn={setLevelNameEn}
          isSaving={createMutation.isPending || updateMutation.isPending}
          onCancel={() => {
            setShowForm(false)
            setEditingLevelId(null)
          }}
          onSubmit={handleSaveLevel}
          isEditing={!!editingLevelId}
        />
      )}

      <div className="text-start">
        <h2 className="text-base font-bold text-slate-800 dark:text-white">
          {isRtl ? 'مستويات الطلاب المتاحة' : 'Available Student Levels'}
        </h2>
      </div>

      <div className="space-y-5">
        {levels.map((lvl) => (
          <StudentLevelCard
            key={lvl.id}
            lvl={lvl}
            onEdit={handleEditLevelClick}
            onDelete={() => handleDeleteLevel(lvl)}
          />
        ))}
      </div>

    </div>
  )
}

