import { useState, useEffect } from 'react';
import { useQuery } from '@tanstack/react-query';
import { managersApi } from '@/shared/services/api/managersApi';
import { landingApi } from '@/shared/services/api/landingApi';
import { normalizeCountries } from '@/shared/utils/countryUtils';

export function useManagers() {
  const [currentPage, setCurrentPage] = useState(1);
  const [searchVal, setSearchVal] = useState('');
  const [committedSearch, setCommittedSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');
  const [needsExtraData, setNeedsExtraData] = useState(false);

  useEffect(() => {
    setCurrentPage(1);
  }, [statusFilter, committedSearch]);

  const commitSearch = () => {
    setCommittedSearch(searchVal);
    setCurrentPage(1);
  };

  const { data: supervisorsData, isLoading: isLoadingSupervisors } = useQuery({
    queryKey: ['admins', statusFilter, currentPage, committedSearch],
    queryFn: () => {
      const params = {
        page: currentPage,
        limit: 10,
        search: committedSearch
      };
      if (statusFilter === 'active') {
        return managersApi.fetchActiveSupervisors(params);
      } else if (statusFilter === 'stopped') {
        return managersApi.fetchStoppedSupervisors(params);
      }
      return managersApi.fetchSupervisors(params);
    },
    staleTime: 5 * 60 * 1000,
  });

  const { data: permissionsData } = useQuery({
    queryKey: ['permissions'],
    queryFn: () => managersApi.fetchPermissions(),
    staleTime: 10 * 60 * 1000,
    enabled: needsExtraData,
    select: (raw) => {
      const items = raw?.data || raw || [];
      const normalized = Array.isArray(items) ? items.map((item) => {
        const perm = item.permission || item;
        const id = perm._id || perm.id || item._id || item.id;
        const name = perm.name || item.name;
        const actions = item.actions || perm.actions || [];
        const keys = Array.isArray(actions)
          ? actions.map((a) => (typeof a === 'object' ? a.key : a)).filter(Boolean)
          : (Array.isArray(item.keys) ? item.keys : []);
        return { id, name, keys };
      }) : [];
      return { ...raw, data: normalized };
    },
  });

  const { data: countriesData } = useQuery({
    queryKey: ['countries'],
    queryFn: () => landingApi.fetchCountries(),
    staleTime: 30 * 60 * 1000,
    enabled: needsExtraData,
  });

  const responseData = supervisorsData || {};
  const dataObj = responseData.data || responseData;

  const supervisorsList = Array.isArray(dataObj)
    ? dataObj
    : Array.isArray(dataObj.admins)
      ? dataObj.admins
      : Array.isArray(dataObj.data)
        ? dataObj.data
        : [];

  const statsObj = responseData.statistics || dataObj.statistics || null;

  const rawPagination = responseData.pagination || dataObj.pagination || responseData.meta || dataObj.meta || null;
  const totalCount = statsObj?.total ?? rawPagination?.total ?? rawPagination?.totalItems ?? supervisorsList.length;
  const totalPagesCount = rawPagination?.numberOfPages
    ?? rawPagination?.pages
    ?? rawPagination?.totalPages
    ?? rawPagination?.pageCount
    ?? rawPagination?.total_pages
    ?? (totalCount > 0 ? Math.ceil(totalCount / 10) : 1);

  const paginationObj = rawPagination
    ? { ...rawPagination, numberOfPages: totalPagesCount, total: totalCount }
    : { numberOfPages: totalPagesCount, total: totalCount };

  return {
    currentPage,
    setCurrentPage,
    searchVal,
    setSearchVal,
    commitSearch,
    statusFilter,
    setStatusFilter,
    enableExtraData: () => setNeedsExtraData(true),
    supervisorsData: {
      ...responseData,
      statistics: statsObj,
      pagination: paginationObj
    },
    supervisors: supervisorsList,
    isLoadingSupervisors,
    permissionsList: permissionsData?.data || [],
    countries: normalizeCountries(countriesData?.data || (Array.isArray(countriesData) ? countriesData : []))
  };
}

import { useState, useEffect, useCallback } from 'react'
import { AnimatePresence, motion } from 'framer-motion'
import { Plus, Package } from 'lucide-react'
import { useTranslation } from 'react-i18next'
import { toast } from 'react-hot-toast'
import { adminPackagesApi } from '@/shared/services/api/adminPackagesApi'
import PackageCard from './components/PackageCard'
import PackageFormPanel from './components/PackageFormPanel'
import FaqInlineForm from './components/FaqInlineForm'
import FaqTable from './components/FaqTable'
import { showDeleteConfirm } from '@/shared/utils/sweetAlert'
import Spinner from '@/shared/components/Spinner'
import { useAdminPermissions } from '@/shared/hooks/useAdminPermissions'
import { normalizeCountries } from '@/shared/utils/countryUtils'

export default function AdminPackages() {
    const { t, i18n } = useTranslation()
    const isRtl = i18n.language.startsWith('ar')
    const { hasPermission, isSuperAdmin } = useAdminPermissions()
    const p = (key) => t(`adminDashboard.packages.${key}`)

    const [packages, setPackages] = useState([])
    const [faqs, setFaqs] = useState([])
    const [explanationLanguages, setExplanationLanguages] = useState([])
    const [countries, setCountries] = useState([])
    const [isLoading, setIsLoading] = useState(true)

    const [pkgPanelOpen, setPkgPanelOpen] = useState(false)
    const [editingPkg, setEditingPkg] = useState(null)
    const [editingFaq, setEditingFaq] = useState(null)
    const [isFaqFormOpen, setIsFaqFormOpen] = useState(false)

    const loadAll = useCallback(async () => {
        setIsLoading(true)
        try {
            const [res, langRes, countriesRes] = await Promise.all([
                adminPackagesApi.fetchPackagesAndFaqs(),
                adminPackagesApi.fetchExplanationLanguages(),
                adminPackagesApi.fetchCountries(),
            ])
            if (res?.packages) setPackages(res.packages)
            if (res?.faqs) setFaqs(res.faqs)
            if (langRes?.success) setExplanationLanguages(langRes.data)
            if (countriesRes?.success) setCountries(normalizeCountries(countriesRes.data))
        } finally {
            setIsLoading(false)
        }
    }, [])

    useEffect(() => {
        loadAll()
    }, [loadAll])

    const handleSavePkg = async (data) => {
        let res;
        if (editingPkg) {
            res = await adminPackagesApi.updatePackage(editingPkg.id, data)
            if (res?.success) setPackages((prev) => prev.map((p) => (p.id === editingPkg.id ? res.data : p)))
        } else {
            res = await adminPackagesApi.createPackage(data)
            if (res?.success) setPackages((prev) => [...prev, res.data])
        }

        if (res?.success) {
            toast.success(isRtl ? 'تم حفظ الباقة بنجاح' : 'Package saved successfully')
            setPkgPanelOpen(false)
        } else {
            const err = Array.isArray(res?.error) ? res.error.join(', ') : res?.error;
            toast.error(err || (isRtl ? 'حدث خطأ أثناء حفظ الباقة' : 'Failed to save package'))
        }
    }

    const executeDelete = async (type, id, name) => {
        const isConfirmed = await showDeleteConfirm(isRtl, name);
        if (!isConfirmed) return;

        if (type === 'package') {
            await adminPackagesApi.deletePackage(id)
            setPackages((prev) => prev.filter((p) => p.id !== id))
        } else {
            await adminPackagesApi.deleteFaq(id)
            setFaqs((prev) => prev.filter((f) => f.id !== id))
        }
    }

    const handleSaveFaq = async (data) => {
        let res;
        if (editingFaq) {
            res = await adminPackagesApi.updateFaq(editingFaq.id, data)
            if (res?.success) setFaqs((prev) => prev.map((f) => (f.id === editingFaq.id ? { ...f, ...res.data } : f)))
        } else {
            res = await adminPackagesApi.createFaq(data)
            if (res?.success) setFaqs((prev) => [...prev, res.data])
        }

        if (res?.success) {
            toast.success(isRtl ? 'تم حفظ السؤال بنجاح' : 'FAQ saved successfully')
            setEditingFaq(null)
            setIsFaqFormOpen(false)
        } else {
            const err = Array.isArray(res?.error) ? res.error.join(', ') : res?.error;
            toast.error(err || (isRtl ? 'حدث خطأ أثناء حفظ السؤال' : 'Failed to save FAQ'))
        }
    }

    const handleEditPkgClick = async (pkg) => {
        const loadingToast = toast.loading(isRtl ? 'جاري تحميل بيانات الباقة...' : 'Loading package details...')
        try {
            const res = await adminPackagesApi.fetchPackageById(pkg.id)
            const pkgData = res?.data || res

            const langId = typeof pkgData.language === 'object' ? pkgData.language?.id || pkgData.language?._id : pkgData.language;

            const mappedPkg = {
                id: pkgData.id || pkgData._id,
                name: typeof pkgData.name === 'object' && pkgData.name !== null ? pkgData.name.ar || '' : pkgData.name || '',
                name_en: typeof pkgData.name === 'object' && pkgData.name !== null ? pkgData.name.en || '' : pkgData.name || '',
                price: pkgData.price,
                sessions_per_month: pkgData.sessionsCount,
                sessions_language: langId,
                country: typeof pkgData.country === 'object' && pkgData.country !== null ? (pkgData.country.id || pkgData.country._id || pkgData.country.name) : (pkgData.country || pkg.country || ''),
                features: Array.isArray(pkgData.features) ? pkgData.features : (pkgData.features?.ar || []),
                features_en: Array.isArray(pkgData.features) ? pkgData.features : (pkgData.features?.en || []),
                image: pkgData.image || pkg.image || null,
            }

            setEditingPkg(mappedPkg)
            setPkgPanelOpen(true)
        } catch (error) {
            console.error('Failed to fetch package details for edit:', error)
            toast.error(isRtl ? 'حدث خطأ أثناء تحميل تفاصيل الباقة' : 'Failed to load package details')
        } finally {
            toast.dismiss(loadingToast)
        }
    }

    const handleEditFaqClick = async (faq) => {
        const loadingToast = toast.loading(isRtl ? 'جاري تحميل بيانات السؤال...' : 'Loading FAQ details...')
        try {
            const res = await adminPackagesApi.fetchFaqById(faq.id)
            const faqData = res?.data || res

            const mappedFaq = {
                id: faqData.id || faqData._id,
                question: typeof faqData.question === 'object' && faqData.question !== null ? faqData.question.ar || '' : faqData.question || '',
                question_en: typeof faqData.question === 'object' && faqData.question !== null ? faqData.question.en || '' : faqData.question || '',
                answer: typeof faqData.answer === 'object' && faqData.answer !== null ? faqData.answer.ar || '' : faqData.answer || '',
                answer_en: typeof faqData.answer === 'object' && faqData.answer !== null ? faqData.answer.en || '' : faqData.answer || '',
            }

            setEditingFaq(mappedFaq)
            setIsFaqFormOpen(true)
        } catch (error) {
            console.error('Failed to fetch FAQ details for edit:', error)
            toast.error(isRtl ? 'حدث خطأ أثناء تحميل تفاصيل السؤال' : 'Failed to load FAQ details')
        } finally {
            toast.dismiss(loadingToast)
        }
    }

    if (isLoading) {
        return (
            <div className="flex h-[60vh] items-center justify-center">
                <Spinner />
            </div>
        )
    }

    const canViewPackages = hasPermission('packages.read') || hasPermission('packages_faqs.read') || isSuperAdmin
    const canCreatePackage = hasPermission('packages.create') || isSuperAdmin
    const canUpdatePackage = hasPermission('packages.update') || isSuperAdmin
    const canDeletePackage = hasPermission('packages.delete') || isSuperAdmin

    const canViewFaqs = hasPermission('faqs.read') || hasPermission('packages_faqs.read') || isSuperAdmin
    const canCreateFaq = hasPermission('faqs.create') || isSuperAdmin
    const canUpdateFaq = hasPermission('faqs.update') || isSuperAdmin
    const canDeleteFaq = hasPermission('faqs.delete') || isSuperAdmin

    if (!canViewPackages && !canViewFaqs) {
        return (
            <div className="flex flex-col items-center justify-center py-20 bg-white dark:bg-slate-900 rounded-3xl border border-slate-100 dark:border-slate-800 text-center p-8">
                <p className="text-slate-600 dark:text-slate-400 font-bold text-base">
                    {isRtl ? 'لا تملك الصلاحيات الكافية لعرض الباقات والأسئلة الشائعة' : 'You do not have permission to view packages or FAQs'}
                </p>
            </div>
        )
    }

    return (
        <div className="space-y-8">
            {canViewPackages && (
                <section>
                    <div className="flex items-center justify-between mb-5">
                        <p className="text-slate-500 dark:text-slate-400 text-sm">
                            {packages.length} {p('available')}
                        </p>
                        {canCreatePackage && (
                            <button
                                onClick={() => { setEditingPkg(null); setPkgPanelOpen(true) }}
                                className="flex items-center gap-2 px-4 py-2.5 bg-[#0f7a6c] text-white rounded-xl text-sm font-semibold hover:bg-[#0d6b5e] transition-colors shadow-sm shadow-[#0f7a6c]/20"
                            >
                                <Plus size={16} />
                                {p('createPackage')}
                            </button>
                        )}
                    </div>

                    {packages.length === 0 ? (
                        <div className="flex flex-col items-center justify-center py-20 bg-white dark:bg-slate-900 rounded-3xl border border-slate-100 dark:border-slate-800 text-center">
                            <div className="w-16 h-16 rounded-full bg-slate-100 dark:bg-slate-800 flex items-center justify-center mb-4">
                                <Package size={28} className="text-slate-300 dark:text-slate-600" />
                            </div>
                            <p className="text-slate-500 dark:text-slate-400 font-medium">{p('noPackages')}</p>
                            <p className="text-slate-400 dark:text-slate-500 text-sm mt-1">{p('noPackagesHint')}</p>
                        </div>
                    ) : (
                        <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-5">
                            <AnimatePresence>
                                {packages.map((pkg) => (
                                    <PackageCard
                                        key={pkg.id}
                                        pkg={pkg}
                                        onEdit={canUpdatePackage ? handleEditPkgClick : null}
                                        onDelete={canDeletePackage ? (id) => executeDelete('package', id, pkg.nameAr || pkg.name_ar || pkg.name || '') : null}
                                        explanationLanguages={explanationLanguages}
                                        countries={countries}
                                    />
                                ))}
                            </AnimatePresence>
                        </div>
                    )}
                </section>
            )}

            {canViewFaqs && (
                <section>
                    <div className="flex items-center justify-between mb-5">
                        <h2 className="text-slate-800 dark:text-white font-bold text-base">{p('faqTitle')}</h2>
                        {canCreateFaq && (
                            <button
                                onClick={() => { setEditingFaq(null); setIsFaqFormOpen((prev) => !prev) }}
                                className="flex items-center gap-2 px-4 py-2.5 bg-[#0f7a6c] text-white rounded-xl text-sm font-semibold hover:bg-[#0d6b5e] transition-colors shadow-sm shadow-[#0f7a6c]/20"
                            >
                                <Plus size={16} className={`transition-transform duration-300 ${isFaqFormOpen ? 'rotate-45' : ''}`} />
                                {isFaqFormOpen ? p('cancel') : p('createFaq')}
                            </button>
                        )}
                    </div>

                    <AnimatePresence initial={false}>
                        {(isFaqFormOpen || editingFaq) && (
                            <motion.div
                                initial={{ height: 0, opacity: 0 }}
                                animate={{ height: 'auto', opacity: 1 }}
                                exit={{ height: 0, opacity: 0 }}
                                className="mb-5 overflow-hidden"
                            >
                                <FaqInlineForm
                                    onSave={handleSaveFaq}
                                    editingFaq={editingFaq}
                                    onCancelEdit={() => { setEditingFaq(null); setIsFaqFormOpen(false) }}
                                />
                            </motion.div>
                        )}
                    </AnimatePresence>

                    <FaqTable
                        faqs={faqs}
                        onEdit={canUpdateFaq ? handleEditFaqClick : null}
                        onDelete={canDeleteFaq ? (id) => {
                            const faq = faqs.find(f => f.id === id);
                            executeDelete('faq', id, faq?.question || '');
                        } : null}
                    />
                </section>
            )}

            <PackageFormPanel
                isOpen={pkgPanelOpen}
                onClose={() => setPkgPanelOpen(false)}
                onSave={handleSavePkg}
                editingPackage={editingPkg}
                explanationLanguages={explanationLanguages}
                countries={countries}
            />
        </div>
    )
}

import { useState, useEffect } from 'react'
import { X } from 'lucide-react'
import { useTranslation } from 'react-i18next'
import Spinner from '@/shared/components/Spinner'
import { EMPTY_FAQ } from './packages_constants'

export default function FaqInlineForm({ onSave, editingFaq, onCancelEdit }) {
  const { t } = useTranslation()
  const p = (key) => t(`adminDashboard.packages.${key}`)

  const [form, setForm] = useState(EMPTY_FAQ)
  const [saving, setSaving] = useState(false)
  useEffect(() => {
    setForm(editingFaq ? { ...EMPTY_FAQ, ...editingFaq } : EMPTY_FAQ)
  }, [editingFaq])

  const setField = (k, v) => setForm((prev) => ({ ...prev, [k]: v }))

  const handleSubmit = async (e) => {
    e.preventDefault()
    if (!form.question.trim()) return
    setSaving(true)
    await onSave(form)
    setForm(EMPTY_FAQ)
    setSaving(false)
  }

  return (
    <div className="bg-white dark:bg-slate-900 rounded-3xl border border-slate-100 dark:border-slate-800/60 shadow-sm overflow-hidden">
      <div className="px-6 py-4 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between">
        <h3 className="font-bold text-slate-800 dark:text-white text-sm">
          {editingFaq ? p('faqEditTitle') : p('faqFormTitle')}
        </h3>
        {editingFaq && (
          <button
            onClick={onCancelEdit}
            className="text-xs text-slate-400 hover:text-slate-600 transition-colors flex items-center gap-1"
          >
            <X size={13} />
            {p('cancelEdit')}
          </button>
        )}
      </div>

      <form onSubmit={handleSubmit} className="p-6 space-y-4">
        <div>
          <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2 text-start">
            {p('questionAr')}
          </label>
          <input
            value={form.question}
            onChange={(e) => setField('question', e.target.value)}
            placeholder={p('questionArPlaceholder')}
            required
            className="w-full bg-[#f3f7f6] dark:bg-slate-900/60 rounded-xl px-4 py-2.5 text-sm outline-none placeholder-slate-400 text-start text-slate-800 dark:text-slate-100 border border-slate-100 dark:border-slate-800"
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-2 text-start">
            {p('answerAr')}
          </label>
          <textarea
            value={form.answer}
            onChange={(e) => setField('answer', e.target.value)}
            rows={4}
            placeholder={p('answerArPlaceholder')}
            className="w-full bg-[#f3f7f6] dark:bg-slate-900/60 rounded-xl px-4 py-3 text-sm outline-none resize-none placeholder-slate-400 text-start text-slate-800 dark:text-slate-100 border border-slate-100 dark:border-slate-800"
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-slate-500 dark:text-slate-400 mb-2">
            {p('questionEn')}
          </label>
          <input
            value={form.question_en}
            onChange={(e) => setField('question_en', e.target.value)}
            placeholder={p('questionEnPlaceholder')}
            className="w-full bg-[#f3f7f6] dark:bg-slate-900/60 rounded-xl px-4 py-2.5 text-sm outline-none placeholder-slate-400 text-slate-800 dark:text-slate-100 border border-slate-100 dark:border-slate-800"
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-slate-500 dark:text-slate-400 mb-2">
            {p('answerEn')}
          </label>
          <textarea
            value={form.answer_en}
            onChange={(e) => setField('answer_en', e.target.value)}
            rows={4}
            placeholder={p('answerEnPlaceholder')}
            className="w-full bg-[#f3f7f6] dark:bg-slate-900/60 rounded-xl px-4 py-3 text-sm outline-none resize-none placeholder-slate-400 text-slate-800 dark:text-slate-100 border border-slate-100 dark:border-slate-800"
          />
        </div>

        <div className="flex justify-start pt-1">
          <button
            type="submit"
            disabled={saving}
            className="px-8 py-2.5 rounded-xl bg-[#0f7a6c] text-white text-sm font-semibold hover:bg-[#0d6b5e] transition-colors disabled:opacity-60 flex items-center gap-2 min-w-[140px] justify-center"
          >
            {saving && <Spinner />}
            {editingFaq ? p('update') : p('add')}
          </button>
        </div>
      </form>
    </div>
  )
}

import { useState, useEffect, useMemo } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { X } from 'lucide-react'
import { createPortal } from 'react-dom'
import { useTranslation } from 'react-i18next'
import Spinner from '@/shared/components/Spinner'
import toast from 'react-hot-toast'
import SelectField from './SelectField'
import PackageImageUpload from './PackageImageUpload'
import PackageFeaturesField from './PackageFeaturesField'
import { sortCountries, getCountryName } from '@/shared/utils/countryUtils'
import {
  EMPTY_PACKAGE,
} from './packages_constants'

export default function PackageFormPanel({ isOpen, onClose, onSave, editingPackage, explanationLanguages = [], countries = [] }) {
  const { t, i18n } = useTranslation()
  const isRtl = i18n.language.startsWith('ar')
  const p = (key) => t(`adminDashboard.packages.${key}`)

  const sortedCountries = useMemo(() => {
    return sortCountries(countries, isRtl)
  }, [countries, isRtl])

  const [form, setForm] = useState(EMPTY_PACKAGE)
  const [saving, setSaving] = useState(false)
  const [imagePreview, setImagePreview] = useState(null)
  const [imageFile, setImageFile] = useState(null)
  useEffect(() => {
    if (isOpen) {
      if (editingPackage) {
        const validLanguage = explanationLanguages.some(l => l.id === editingPackage.sessions_language)
          ? editingPackage.sessions_language
          : (explanationLanguages?.[0]?.id || '');

        setForm({
          ...EMPTY_PACKAGE,
          ...editingPackage,
          country: editingPackage.country || editingPackage.countryId || '',
          sessions_language: validLanguage,
          features: editingPackage.features?.length ? [...editingPackage.features] : [''],
          features_en: editingPackage.features_en?.length ? [...editingPackage.features_en] : [''],
        })
        setImagePreview(editingPackage.image || null)
        setImageFile(null)
      } else {
        setForm({
          ...EMPTY_PACKAGE,
          country: '',
          sessions_language: explanationLanguages?.[0]?.id || ''
        })
        setImagePreview(null)
        setImageFile(null)
      }
    }
  }, [isOpen, editingPackage, explanationLanguages])

  const handleImageChange = (e) => {
    const file = e.target.files[0]
    if (!file) return
    setImageFile(file)
    const reader = new FileReader()
    reader.onload = (ev) => setImagePreview(ev.target.result)
    reader.readAsDataURL(file)
  }

  const setField = (key, value) => setForm((prev) => ({ ...prev, [key]: value }))

  const setFeature = (index, value) => {
    const updated = [...form.features]
    updated[index] = value
    setField('features', updated)
  }

  const setFeatureEn = (index, value) => {
    const updated = [...form.features_en]
    updated[index] = value
    setField('features_en', updated)
  }

  const addFeature = () => {
    setField('features', [...form.features, ''])
    setField('features_en', [...form.features_en, ''])
  }

  const removeFeature = (index) => {
    setField('features', form.features.filter((_, i) => i !== index))
    setField('features_en', form.features_en.filter((_, i) => i !== index))
  }

  const handleSubmit = async (e) => {
    e.preventDefault()

    const rawFeatures = form.features
      .map(f => typeof f === 'string' ? f.trim() : '')
      .filter(f => f.length > 0)

    const rawFeaturesEn = form.features_en
      .map(f => typeof f === 'string' ? f.trim() : '')
      .filter(f => f.length > 0)

    if (rawFeatures.length === 0) {
      toast.error(isRtl ? 'يجب إضافة ميزة واحدة على الأقل للباقة' : 'At least one feature is required')
      return
    }

    const hasShortAr = rawFeatures.some(f => f.length < 3)
    if (hasShortAr) {
      toast.error(isRtl ? 'يجب أن لا يقل طول نص كل ميزة عن 3 أحرف' : 'Each feature must be at least 3 characters')
      return
    }

    const finalFeaturesEn = rawFeatures.map((feat, idx) => {
      const enVal = rawFeaturesEn[idx]
      return (enVal && enVal.trim().length >= 3) ? enVal.trim() : feat
    })

    setSaving(true)
    const cleaned = {
      ...form,
      price: Number(form.price),
      sessions_per_month: Number(form.sessions_per_month),
      features: rawFeatures,
      features_en: finalFeaturesEn,
      imageFile
    }
    await onSave(cleaned)
    setSaving(false)
  }

  return createPortal(
    <AnimatePresence>
      {isOpen && (
        <div className="fixed inset-0 z-[9999] flex items-center justify-center p-4" dir={isRtl ? 'rtl' : 'ltr'}>
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={onClose}
            className="absolute inset-0 bg-slate-950/40 dark:bg-black/60 backdrop-blur-sm"
          />
          <motion.div
            initial={{ opacity: 0, scale: 0.95, y: 12 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.95, y: 12 }}
            transition={{ duration: 0.25, ease: 'easeOut' }}
            className="relative z-10 w-full max-w-2xl max-h-[90vh] bg-white dark:bg-slate-900 rounded-3xl shadow-2xl flex flex-col border border-slate-100 dark:border-slate-800/60 overflow-hidden"
          >
            <div className="flex items-center justify-between px-6 py-5 border-b border-slate-100/60 dark:border-slate-800/60 shrink-0 bg-slate-50/50 dark:bg-slate-900/50">
              <h2 className="font-bold text-slate-800 dark:text-white text-base">
                {editingPackage ? p('editPackage') : p('createPackage')}
              </h2>
              <button
                onClick={onClose}
                className="p-2 rounded-xl hover:bg-slate-100 dark:hover:bg-slate-800 text-slate-400 hover:text-slate-600 transition-colors"
                aria-label={p('cancel')}
              >
                <X size={18} />
              </button>
            </div>

            <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto px-6 py-5 space-y-5">
              <PackageImageUpload
                imagePreview={imagePreview}
                onImageChange={handleImageChange}
                label={p('packageImage')}
                hint={p('imageHint')}
                packageName={form.name || form.name_en}
              />

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label htmlFor="name" className="block text-xs font-medium text-slate-500 mb-1.5 text-start">{p('packageNameAr')}</label>
                  <input
                    id="name"
                    name="name"
                    value={form.name}
                    onChange={(e) => setField('name', e.target.value)}
                    placeholder={p('packageNameArPlaceholder')}
                    required
                    dir="rtl"
                    className="w-full bg-[#f3f7f6] dark:bg-slate-900/60 rounded-xl px-4 py-2.5 text-sm outline-none placeholder-slate-400 text-start text-slate-800 dark:text-slate-100"
                  />
                </div>
                <div>
                  <label htmlFor="name_en" className="block text-xs font-medium text-slate-500 mb-1.5 text-start">{p('packageNameEn')}</label>
                  <input
                    id="name_en"
                    name="name_en"
                    value={form.name_en}
                    onChange={(e) => setField('name_en', e.target.value)}
                    placeholder={p('packageNameEnPlaceholder')}
                    dir="ltr"
                    className="w-full bg-[#f3f7f6] dark:bg-slate-900/60 rounded-xl px-4 py-2.5 text-sm outline-none placeholder-slate-400 text-start text-slate-800 dark:text-slate-100"
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label htmlFor="price" className="block text-xs font-medium text-slate-500 mb-1.5 text-start">{p('price')}</label>
                  <input
                    id="price"
                    name="price"
                    type="number"
                    value={form.price}
                    onChange={(e) => setField('price', e.target.value)}
                    placeholder={p('pricePlaceholder')}
                    required
                    dir="ltr"
                    className="w-full bg-[#f3f7f6] dark:bg-slate-900/60 rounded-xl px-4 py-2.5 text-sm outline-none placeholder-slate-400 text-start text-slate-800 dark:text-slate-100"
                  />
                </div>
                <div>
                  <label htmlFor="sessions_per_month" className="block text-xs font-medium text-slate-500 mb-1.5 text-start">{p('sessionsCount')}</label>
                  <input
                    id="sessions_per_month"
                    name="sessions_per_month"
                    type="number"
                    min="1"
                    value={form.sessions_per_month ?? ''}
                    onChange={(e) => setField('sessions_per_month', e.target.value)}
                    placeholder={p('sessionsCount')}
                    required
                    dir="ltr"
                    className="w-full bg-[#f3f7f6] dark:bg-slate-900/60 rounded-xl px-4 py-2.5 text-sm outline-none placeholder-slate-400 text-start text-slate-800 dark:text-slate-100"
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-3">
                <SelectField
                  id="country"
                  label={t('adminDashboard.packages.country', 'الدولة')}
                  value={form.country || ''}
                  onChange={(v) => setField('country', v)}
                  options={[
                    { value: '', label: t('adminDashboard.packages.allCountries', 'جميع الدول (عام)') },
                    ...sortedCountries.map((c) => {
                      const cid = c.id || c._id
                      const name = getCountryName(c, isRtl)
                      const flag = c.flag ? `${c.flag} ` : ''
                      return {
                        value: cid || name,
                        label: `${flag}${name}`,
                      }
                    }),
                  ]}
                  placeholder={t('adminDashboard.packages.selectCountry', 'اختر الدولة')}
                />
                <SelectField
                  id="sessions_language"
                  label={p('language')}
                  value={form.sessions_language}
                  onChange={(v) => setField('sessions_language', v)}
                  options={explanationLanguages.map((lang) => ({
                    value: lang.id || lang._id,
                    label: typeof lang.name === 'object' && lang.name !== null
                      ? (isRtl ? lang.name.ar || lang.name.en : lang.name.en || lang.name.ar)
                      : lang.name,
                  }))}
                  placeholder={p('language')}
                />
              </div>

              <div id="features" tabIndex={-1} className="outline-none">
                <PackageFeaturesField
                  features={form.features}
                  featuresEn={form.features_en}
                  onAddFeature={addFeature}
                  onRemoveFeature={removeFeature}
                  onFeatureChange={setFeature}
                  onFeatureEnChange={setFeatureEn}
                />
              </div>
            </form>

            <div className="px-6 py-4 border-t border-slate-100/60 dark:border-slate-800/60 flex gap-3 shrink-0 bg-slate-50/50 dark:bg-slate-900/50">
              <button
                type="button"
                onClick={onClose}
                className="flex-1 py-2.5 rounded-xl border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 text-sm font-semibold hover:bg-slate-50 dark:hover:bg-slate-900 transition-colors"
              >
                {p('cancel')}
              </button>
              <button
                onClick={handleSubmit}
                disabled={saving}
                className="relative flex-1 py-2.5 rounded-xl bg-[#0f7a6c] text-white text-sm font-semibold hover:bg-[#0d6b5e] transition-colors disabled:opacity-60 flex items-center justify-center min-w-[140px]"
              >
                {saving && (
                  <span className="absolute rtl:right-4 ltr:left-4 flex items-center justify-center">
                    <Spinner size="sm" />
                  </span>
                )}
                <span>{p('save')}</span>
              </button>
            </div>
          </motion.div>
        </div>
      )}
    </AnimatePresence>,
    document.body
  )
}

import { useState, useEffect, useCallback } from 'react'
import { useTranslation } from 'react-i18next'
import Spinner from '@/shared/components/Spinner'
import { adminPaymentsApi } from '@/shared/services/api/adminPaymentsApi'
import { showSuccessToast } from '@/shared/utils/sweetAlert'
import PaymentsStats from './components/PaymentsStats'
import PaymentsFilters from './components/PaymentsFilters'
import PaymentsTable from './components/PaymentsTable'

export default function AdminPayments() {
  const { i18n } = useTranslation()
  const isRtl = i18n.language.startsWith('ar')

  const [stats, setStats] = useState(null)
  const [payments, setPayments] = useState([])
  const [loading, setLoading] = useState(true)
  const [isExporting, setIsExporting] = useState(false)

  const [activePeriod, setActivePeriod] = useState('annual')
  const [activeStatus, setActiveStatus] = useState('all')
  const [searchValue, setSearchValue] = useState('')

  const loadStats = useCallback(async () => {
    const res = await adminPaymentsApi.fetchPaymentsStats(activePeriod)
    if (res?.data) setStats(res.data)
  }, [activePeriod])

  const loadPayments = useCallback(async () => {
    setLoading(true)
    const res = await adminPaymentsApi.fetchPayments({
      period: activePeriod,
      status: activeStatus,
      search: searchValue,
    })
    if (res?.data) setPayments(res.data)
    setLoading(false)
  }, [activePeriod, activeStatus, searchValue])

  useEffect(() => {
    loadStats()
  }, [loadStats])

  useEffect(() => {
    loadPayments()
  }, [loadPayments])

  const handleApprove = async (id) => {
    const res = await adminPaymentsApi.approvePayment(id)
    if (res?.success) {
      setPayments((prev) =>
        prev.map((item) => (item.id === id ? { ...item, status: 'paid' } : item))
      )
      loadStats()
    }
  }

  const handleReject = async (id) => {
    const res = await adminPaymentsApi.rejectPayment(id)
    if (res?.success) {
      setPayments((prev) =>
        prev.map((item) => (item.id === id ? { ...item, status: 'failed' } : item))
      )
      loadStats()
    }
  }

  const handleExport = async () => {
    setIsExporting(true)
    try {
      await adminPaymentsApi.exportCsv()
      showSuccessToast(isRtl ? 'تم تصدير ملف CSV بنجاح!' : 'CSV exported successfully!', isRtl)
    } finally {
      setIsExporting(false)
    }
  }

  const handleReviewAll = () => {
    setActiveStatus('pending')
  }

  if (loading && !stats) {
    return (
      <div className="flex items-center justify-center h-60">
        <Spinner />
      </div>
    )
  }

  return (
    <div className="space-y-8">
      {stats && <PaymentsStats stats={stats} />}

      <PaymentsFilters
        activePeriod={activePeriod}
        setActivePeriod={setActivePeriod}
        activeStatus={activeStatus}
        setActiveStatus={setActiveStatus}
        searchValue={searchValue}
        setSearchValue={setSearchValue}
        onExport={handleExport}
        isExporting={isExporting}
      />

      {loading ? (
        <div className="flex items-center justify-center h-40">
          <Spinner />
        </div>
      ) : (
        <PaymentsTable
          payments={payments}
          onApprove={handleApprove}
          onReject={handleReject}
          onReviewAll={handleReviewAll}
        />
      )}
    </div>
  )
}

