import { useState, useEffect, useCallback } from 'react'
import { Plus, X } from 'lucide-react'
import { useTranslation } from 'react-i18next'
import { toast } from 'react-hot-toast'
import { createPortal } from 'react-dom'
import Spinner from '@/shared/components/Spinner'
import { adminRewardsApi } from '@/shared/services/api/adminRewardsApi'
import { showDeleteConfirm, showSuccessToast, showErrorToast, showRewardDetails } from '@/shared/utils/sweetAlert'
import RewardForm from './components/RewardForm'
import RewardsSuggestions from './components/RewardsSuggestions'
import RewardsGrid from './components/RewardsGrid'
import { useAdminPermissions } from '@/shared/hooks/useAdminPermissions'

export default function AdminRewards() {
  const { t, i18n } = useTranslation()
  const isRtl = i18n.language.startsWith('ar')
  const { hasPermission, isSuperAdmin } = useAdminPermissions()
  const p = (key) => t(`adminDashboard.rewards.${key}`, key)

  const [stats, setStats] = useState(null)
  const [rewards, setRewards] = useState([])
  const [suggestions, setSuggestions] = useState([])
  const [suggestionsStats, setSuggestionsStats] = useState(null)
  const [suggestionsFilter, setSuggestionsFilter] = useState('all')
  const [isSuggestionsLoading, setIsSuggestionsLoading] = useState(false)
  const [loading, setLoading] = useState(true)

  const canViewRewards = hasPermission('rewards.read') || hasPermission('rewards_suggestions.read') || isSuperAdmin
  const canViewSuggestions = hasPermission('suggested_rewards.read') || hasPermission('rewards_suggestions.read') || isSuperAdmin
  const canCreateReward = hasPermission('rewards.create') || isSuperAdmin
  const canEditReward = hasPermission('rewards.update') || isSuperAdmin
  const canDeleteReward = hasPermission('rewards.delete') || isSuperAdmin
  const canDeleteSuggestion = hasPermission('suggested_rewards.delete') || isSuperAdmin
  const canApproveSuggestion = hasPermission('suggested_rewards.accept') || isSuperAdmin
  const canRejectSuggestion = hasPermission('suggested_rewards.reject') || isSuperAdmin

  const [activeMainTab, setActiveMainTab] = useState(() => (canViewRewards ? 'rewards' : 'suggestions'))
  const [showForm, setShowForm] = useState(false)
  const [editingReward, setEditingReward] = useState(null)
  const [isSaving, setIsSaving] = useState(false)

  useEffect(() => {
    if (!canViewRewards && canViewSuggestions) {
      setActiveMainTab('suggestions')
    } else if (canViewRewards && !canViewSuggestions) {
      setActiveMainTab('rewards')
    }
  }, [canViewRewards, canViewSuggestions])

  const loadSuggestionsByStatus = useCallback(async (status) => {
    setIsSuggestionsLoading(true)
    setSuggestionsFilter(status)
    const res = await adminRewardsApi.fetchSuggestions(status)
    if (res?.success) {
      setSuggestions(res.data)
      if (res.stats) {
        setSuggestionsStats(res.stats)
      }
    }
    setIsSuggestionsLoading(false)
  }, [])

  const loadData = useCallback(async () => {
    setLoading(true)
    const [statsRes, rewardsRes, suggestionsRes] = await Promise.all([
      adminRewardsApi.fetchStats(),
      adminRewardsApi.fetchRewards(),
      adminRewardsApi.fetchSuggestions(suggestionsFilter),
    ])
    if (statsRes?.data) setStats(statsRes.data)
    if (rewardsRes?.success) setRewards(rewardsRes.data)
    if (suggestionsRes?.success) {
      setSuggestions(suggestionsRes.data)
      if (suggestionsRes.stats) {
        setSuggestionsStats(suggestionsRes.stats)
      }
    }
    setLoading(false)
  }, [suggestionsFilter])

  useEffect(() => {
    loadData()
  }, [loadData])

  const handleEditRewardClick = async (reward, switchTab = false) => {
    const loadingToast = toast.loading(isRtl ? 'جاري تحميل بيانات المكافأة...' : 'Loading reward details...')
    try {
      const res = await adminRewardsApi.fetchRewardById(reward.id || reward._id)
      if (res?.success && res.data) {
        setEditingReward(res.data)
        setShowForm(true)
      } else {
        setEditingReward(reward)
        setShowForm(true)
      }
      if (switchTab) setActiveMainTab('rewards')
    } catch (error) {
      console.error('Failed to fetch reward details for edit:', error)
      setEditingReward(reward)
      setShowForm(true)
      if (switchTab) setActiveMainTab('rewards')
    } finally {
      toast.dismiss(loadingToast)
    }
  }

  const handleSaveReward = async (rewardData) => {
    setIsSaving(true)
    try {
      if (editingReward) {
        const res = await adminRewardsApi.updateReward(editingReward.id || editingReward._id, rewardData)
        if (res?.success) {
          showSuccessToast(isRtl ? 'تم تحديث المكافأة بنجاح' : 'Reward updated successfully', isRtl)
          loadData()
        } else {
          showErrorToast(isRtl ? 'حدث خطأ أثناء التحديث' : 'Failed to update reward', isRtl)
        }
      } else {
        const res = await adminRewardsApi.createReward(rewardData)
        if (res?.success) {
          showSuccessToast(isRtl ? 'تم إضافة المكافأة بنجاح' : 'Reward added successfully', isRtl)
          loadData()
        } else {
          showErrorToast(isRtl ? 'حدث خطأ أثناء الإضافة' : 'Failed to add reward', isRtl)
        }
      }
      setShowForm(false)
      setEditingReward(null)
    } finally {
      setIsSaving(false)
    }
  }

  const handleDeleteReward = async (reward) => {
    const rewardName = typeof reward.name === 'object' ? (isRtl ? reward.name.ar : reward.name.en) : reward.name;
    const isConfirmed = await showDeleteConfirm(isRtl, rewardName);
    if (!isConfirmed) return;

    const res = await adminRewardsApi.deleteReward(reward.id || reward._id)
    if (res?.success) {
      showSuccessToast(isRtl ? 'تم الحذف بنجاح' : 'Deleted successfully', isRtl)
      loadData()
    } else {
      showErrorToast(isRtl ? 'فشل الحذف' : 'Deletion failed', isRtl)
    }
  }

  const handleApproveSuggestion = async (id) => {
    const res = await adminRewardsApi.approveSuggestion(id)
    if (res?.success) {
      showSuccessToast(isRtl ? 'تم قبول المقترح بنجاح' : 'Suggestion approved successfully', isRtl)
      loadSuggestionsByStatus(suggestionsFilter)
    } else {
      showErrorToast(res?.error || (isRtl ? 'فشل قبول المقترح' : 'Failed to approve suggestion'), isRtl)
    }
  }

  const handleRejectSuggestion = async (id) => {
    const res = await adminRewardsApi.rejectSuggestion(id)
    if (res?.success) {
      showSuccessToast(isRtl ? 'تم رفض المقترح بنجاح' : 'Suggestion rejected successfully', isRtl)
      loadSuggestionsByStatus(suggestionsFilter)
    } else {
      showErrorToast(res?.error || (isRtl ? 'فشل رفض المقترح' : 'Failed to reject suggestion'), isRtl)
    }
  }

  const handleDeleteSuggestion = async (suggestion) => {
    const suggestionName = typeof suggestion.name === 'object' ? (isRtl ? suggestion.name.ar : suggestion.name.en) : suggestion.name;
    const isConfirmed = await showDeleteConfirm(isRtl, suggestionName);
    if (!isConfirmed) return;

    const res = await adminRewardsApi.deleteSuggestion(suggestion.id || suggestion._id)
    if (res?.success) {
      showSuccessToast(isRtl ? 'تم حذف المقترح بنجاح' : 'Suggestion deleted successfully', isRtl)
      loadSuggestionsByStatus(suggestionsFilter)
    } else {
      showErrorToast(res?.error || (isRtl ? 'فشل حذف المقترح' : 'Failed to delete suggestion'), isRtl)
    }
  }

  if (loading && !stats) {
    return (
      <div className="flex items-center justify-center h-60">
        <Spinner />
      </div>
    )
  }

  if (!canViewRewards && !canViewSuggestions) {
    return (
      <div className="flex flex-col items-center justify-center py-20 bg-white dark:bg-slate-900 rounded-3xl border border-slate-100 dark:border-slate-800 text-center p-8">
        <p className="text-slate-600 dark:text-slate-400 font-bold text-base">
          {isRtl ? 'لا تملك الصلاحيات الكافية لعرض نظام المكافآت والمقترحات' : 'You do not have permission to view rewards or suggestions'}
        </p>
      </div>
    )
  }

  return (
    <div className="space-y-8" dir={isRtl ? 'rtl' : 'ltr'}>
      <div className="bg-white dark:bg-slate-900 rounded-3xl border border-slate-100 dark:border-slate-800/60 p-6 shadow-sm flex items-center justify-between">
        <div className="flex flex-col items-center">
          <span className="text-slate-400 dark:text-slate-500 text-xs font-semibold">
            {p('statTotalRewards', 'إجمالي المكافآت')}
          </span>
          <span className="text-3xl font-extrabold text-[#0f7a6c] dark:text-emerald-400 mt-1.5">
            {rewards.length}
          </span>
        </div>
      </div>

      <div className="flex items-center gap-2 border-b border-slate-200 dark:border-slate-800 pb-2 overflow-x-auto">
        {canViewRewards && (
          <button
            onClick={() => setActiveMainTab('rewards')}
            className={`px-5 py-2.5 rounded-2xl text-sm font-bold transition-all whitespace-nowrap ${activeMainTab === 'rewards'
              ? 'bg-brand-50 text-brand-600 dark:bg-brand-900/30 dark:text-brand-400'
              : 'text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200 hover:bg-slate-50 dark:hover:bg-slate-800/50'
              }`}
          >
            {isRtl ? 'المكافآت المتاحة' : 'Available Rewards'}
          </button>
        )}
        {canViewSuggestions && (
          <button
            onClick={() => setActiveMainTab('suggestions')}
            className={`px-5 py-2.5 rounded-2xl text-sm font-bold transition-all whitespace-nowrap ${activeMainTab === 'suggestions'
              ? 'bg-brand-50 text-brand-600 dark:bg-brand-900/30 dark:text-brand-400'
              : 'text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200 hover:bg-slate-50 dark:hover:bg-slate-800/50'
              }`}
          >
            {isRtl ? 'المكافآت المقترحة' : 'Suggested Rewards'}
          </button>
        )}
      </div>

      {activeMainTab === 'rewards' && canViewRewards ? (
        <div className="space-y-6">
          <div className="flex items-center justify-between">
            <h2 className="text-slate-800 dark:text-white font-bold text-base">
              {p('availableRewardsTitle', 'المكافآت المتاحة')}
            </h2>
            {canCreateReward && (
              <button
                onClick={() => {
                  setEditingReward(null)
                  setShowForm(!showForm)
                }}
                className="flex items-center gap-2 px-4 py-2.5 bg-[#0f7a6c] text-white rounded-xl text-xs font-bold hover:bg-[#0d6b5e] transition-colors shadow-sm shadow-[#0f7a6c]/20"
              >
                <Plus size={16} />
                {p('createRewardBtn', 'إنشاء مكافأة')}
              </button>
            )}
          </div>

          <RewardsGrid
            rewards={rewards}
            onView={(item) => showRewardDetails(item, isRtl)}
            onEdit={canEditReward ? handleEditRewardClick : null}
            onDelete={canDeleteReward ? handleDeleteReward : null}
          />
        </div>
      ) : canViewSuggestions ? (
        <RewardsSuggestions
          suggestions={suggestions}
          stats={suggestionsStats || stats || {}}
          activeFilter={suggestionsFilter}
          onFilterChange={loadSuggestionsByStatus}
          isLoading={isSuggestionsLoading}
          onView={(item) => showRewardDetails(item, isRtl)}
          onApprove={canApproveSuggestion ? handleApproveSuggestion : null}
          onReject={canRejectSuggestion ? handleRejectSuggestion : null}
          onDelete={canDeleteSuggestion ? handleDeleteSuggestion : null}
        />
      ) : null}

      {showForm && createPortal(
        <div className="fixed inset-0 z-[9999] flex items-center justify-center p-4 bg-slate-900/50 backdrop-blur-sm overflow-y-auto">
          <div className="bg-white dark:bg-slate-900 rounded-3xl shadow-2xl w-full max-w-3xl my-8 relative flex flex-col max-h-[90vh]">
            <div className="p-6 border-b border-slate-100 dark:border-slate-800/60 flex items-center justify-between shrink-0">
              <h2 className="text-xl font-bold text-slate-800 dark:text-white">
                {editingReward ? (isRtl ? 'تعديل المكافأة' : 'Edit Reward') : (isRtl ? 'إضافة مكافأة' : 'Add Reward')}
              </h2>
              <button
                onClick={() => { setShowForm(false); setEditingReward(null); }}
                className="p-2 text-slate-400 hover:text-slate-600 bg-slate-100 rounded-full hover:bg-slate-200 dark:bg-slate-800 dark:hover:bg-slate-700 dark:hover:text-slate-300 transition-colors"
              >
                <X size={20} />
              </button>
            </div>
            <div className="p-6 overflow-y-auto">
              <RewardForm
                onSave={handleSaveReward}
                onCancel={() => {
                  setShowForm(false)
                  setEditingReward(null)
                }}
                editingReward={editingReward}
                isSaving={isSaving}
              />
            </div>
          </div>
        </div>,
        document.body
      )}
    </div>
  )
}

import { useState, useEffect } from 'react'
import { useTranslation } from 'react-i18next'
import { Loader2 } from 'lucide-react'

const COLOR_OPTIONS = [
  { key: 'red', labelAr: 'احمر', labelEn: 'Red', bgColor: '#fee2e2', textColor: '#dc2626' },
  { key: 'green', labelAr: 'اخضر', labelEn: 'Green', bgColor: '#d1fae5', textColor: '#059669' },
  { key: 'yellow', labelAr: 'اصفر', labelEn: 'Yellow', bgColor: '#fef3c7', textColor: '#d97706' },
  { key: 'blue', labelAr: 'ازرق', labelEn: 'Blue', bgColor: '#dbeafe', textColor: '#2563eb' },
  { key: 'purple', labelAr: 'بنفسجي', labelEn: 'Purple', bgColor: '#f3e8ff', textColor: '#7c3aed' },
]

export default function RewardForm({ onSave, onCancel, editingReward, isSaving = false }) {
  const { t, i18n } = useTranslation()
  const isRtl = i18n.language.startsWith('ar')
  const p = (key) => t(`adminDashboard.rewards.${key}`, key)

  const [name, setName] = useState('')
  const [nameEn, setNameEn] = useState('')
  const [emoji, setEmoji] = useState('⭐')
  const [selectedColor, setSelectedColor] = useState(COLOR_OPTIONS[0])
  const [description, setDescription] = useState('')
  const [descriptionEn, setDescriptionEn] = useState('')
  useEffect(() => {
    if (editingReward) {
      const arName = typeof editingReward.name === 'object' ? (editingReward.name?.ar || '') : (editingReward.name || '')
      const enName = typeof editingReward.name === 'object' ? (editingReward.name?.en || '') : (editingReward.name || '')
      setName(arName)
      setNameEn(enName)

      setEmoji(editingReward.icon || editingReward.emoji || '⭐')

      const bgColor = editingReward.backgroundColor || editingReward.bgColor
      const matched = COLOR_OPTIONS.find((c) => c.bgColor === bgColor)
      if (matched) setSelectedColor(matched)
      else setSelectedColor(COLOR_OPTIONS[0])

      const arDesc = typeof editingReward.description === 'object' ? (editingReward.description?.ar || '') : (editingReward.description || '')
      const enDesc = typeof editingReward.description === 'object' ? (editingReward.description?.en || '') : (editingReward.description || '')
      setDescription(arDesc)
      setDescriptionEn(enDesc)
    } else {
      setName('')
      setNameEn('')
      setEmoji('⭐')
      setSelectedColor(COLOR_OPTIONS[0])
      setDescription('')
      setDescriptionEn('')
    }
  }, [editingReward])

  const handleSubmit = (e) => {
    e.preventDefault()
    if (!name.trim()) return
    onSave({
      name,
      nameEn,
      emoji,
      bgColor: selectedColor.bgColor,
      textColor: selectedColor.textColor,
      description,
      descriptionEn,
    })
  }

  return (
    <div className="bg-white dark:bg-slate-900 rounded-3xl border border-slate-100 dark:border-slate-800/60 shadow-sm p-6 max-w-4xl mx-auto">
      <h3 className="font-bold text-slate-800 dark:text-white text-base mb-6 text-end">
        {editingReward ? p('editRewardTitle') : p('newRewardTitle')}
      </h3>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="block text-xs font-semibold text-slate-500 mb-2">Reward Name</label>
            <input
              type="text"
              value={nameEn}
              onChange={(e) => setNameEn(e.target.value)}
              placeholder="Name Reward"
              required
              minLength={2}
              maxLength={100}
              className="w-full bg-[#f3f7f6] dark:bg-slate-950 rounded-2xl px-4 py-3 text-sm outline-none placeholder-slate-400 text-start text-slate-800 dark:text-slate-100"
            />
          </div>
          <div>
            <label className="block text-xs font-semibold text-slate-500 mb-2 text-end">اسم المكافأة</label>
            <input
              type="text"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="مثال: نجم القرآن"
              required
              minLength={2}
              maxLength={100}
              className="w-full bg-[#f3f7f6] dark:bg-slate-950 rounded-2xl px-4 py-3 text-sm outline-none placeholder-slate-400 text-end text-slate-800 dark:text-slate-100"
            />
          </div>
        </div>

        <div>
          <label className="block text-xs font-semibold text-slate-500 mb-2 text-end">أيقونة (إيموجي)</label>
          <input
            type="text"
            value={emoji}
            onChange={(e) => setEmoji(e.target.value)}
            required
            className="w-full bg-[#f3f7f6] dark:bg-slate-950 rounded-2xl px-4 py-3 text-sm outline-none text-center text-slate-800 dark:text-slate-100"
          />
        </div>

        <div>
          <label className="block text-xs font-semibold text-slate-500 mb-2 text-end">لون الخلفية للمكافأة</label>
          <select
            value={selectedColor.key}
            onChange={(e) => {
              const matched = COLOR_OPTIONS.find((c) => c.key === e.target.value)
              if (matched) setSelectedColor(matched)
            }}
            className="w-full bg-[#f3f7f6] dark:bg-slate-950 rounded-2xl px-4 py-3 text-sm outline-none text-end text-slate-700 dark:text-slate-300"
          >
            {COLOR_OPTIONS.map((opt) => (
              <option key={opt.key} value={opt.key}>
                {isRtl ? opt.labelAr : opt.labelEn}
              </option>
            ))}
          </select>
        </div>

        <div>
          <label className="block text-xs font-semibold text-slate-500 mb-2 text-end">وصف المكافأة</label>
          <textarea
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            rows={4}
            required
            minLength={2}
            maxLength={500}
            placeholder="اشرح متى ولمن تُمنح هذه المكافأة..."
            className="w-full bg-[#f3f7f6] dark:bg-slate-950 rounded-2xl px-4 py-3 text-sm outline-none resize-none placeholder-slate-400 text-end text-slate-800 dark:text-slate-100"
          />
        </div>

        <div>
          <label className="block text-xs font-semibold text-slate-500 mb-2">Reward Describe</label>
          <textarea
            value={descriptionEn}
            onChange={(e) => setDescriptionEn(e.target.value)}
            rows={4}
            required
            minLength={2}
            maxLength={500}
            placeholder="Describe"
            className="w-full bg-[#f3f7f6] dark:bg-slate-950 rounded-2xl px-4 py-3 text-sm outline-none resize-none placeholder-slate-400 text-slate-800 dark:text-slate-100"
          />
        </div>

        <div className="flex justify-end gap-3 pt-3">
          <button
            type="button"
            onClick={onCancel}
            disabled={isSaving}
            className="px-6 py-2.5 bg-slate-100 dark:bg-slate-800 hover:bg-slate-200 text-slate-600 dark:text-slate-300 rounded-2xl text-xs font-bold transition-colors disabled:opacity-50"
          >
            {p('cancelBtn')}
          </button>
          <button
            type="submit"
            disabled={isSaving}
            className="px-8 py-2.5 bg-[#0f7a6c] hover:bg-[#0d6b5e] text-white rounded-2xl text-xs font-bold transition-all shadow-sm shadow-[#0f7a6c]/20 disabled:opacity-70 flex items-center justify-center gap-2"
          >
            {isSaving && <Loader2 className="w-4 h-4 animate-spin" />}
            {p('saveBtn')}
          </button>
        </div>
      </form>
    </div>
  )
}

import { useState, useEffect, useMemo, useCallback } from 'react'
import { useTranslation } from 'react-i18next'
import { Search, Calendar, ChevronLeft, ChevronRight, X } from 'lucide-react'
import { adminSessionsApi } from '@/shared/services/api/adminSessionsApi'
import { teachersApi } from '@/shared/services/api/teachersApi'
import Spinner from '@/shared/components/Spinner'
import { showSuccessToast, showErrorToast } from '@/shared/utils/sweetAlert'
import StatCard from './components/StatCard'
import SessionRow from './components/SessionRow'

const STATUS_TABS = [
  { key: 'all', label: 'الكل' },
  { key: 'scheduled', label: 'مجدولة' },
  { key: 'live', label: 'مباشرة الآن' },
  { key: 'completed', label: 'مكتملة' },
  { key: 'cancelled', label: 'ملغاة' },
]

export default function AdminSessions() {
  const { t, i18n } = useTranslation()
  const isRtl = i18n?.language?.startsWith('ar') ?? true

  const [apiStats, setApiStats] = useState(null)
  const [sessions, setSessions] = useState([])
  const [teachers, setTeachers] = useState([])
  const [isLoading, setIsLoading] = useState(true)
  const [searchQuery, setSearchQuery] = useState('')
  const [debouncedSearch, setDebouncedSearch] = useState('')
  const [activeTab, setActiveTab] = useState('all')
  const [currentPage, setCurrentPage] = useState(1)
  const [totalPages, setTotalPages] = useState(1)
  const [totalCount, setTotalCount] = useState(0)
  const [expandedRow, setExpandedRow] = useState(null)
  const [expandedPanel, setExpandedPanel] = useState(null)

  const itemsPerPage = 10

  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedSearch(searchQuery)
      setCurrentPage(1)
    }, 350)
    return () => clearTimeout(timer)
  }, [searchQuery])

  useEffect(() => {
    let active = true
    const loadTeachers = async () => {
      try {
        const res = await teachersApi.fetchTeachers({ limit: 100 })
        if (!active) return
        const list = res?.data || (Array.isArray(res) ? res : [])
        const formatted = (Array.isArray(list) ? list : []).map((tch) => {
          let nameStr = ''
          if (typeof tch.displayName === 'string' && tch.displayName.trim()) {
            nameStr = tch.displayName.trim()
          } else if (typeof tch.name === 'string' && tch.name.trim()) {
            nameStr = tch.name.trim()
          } else if (typeof tch.name === 'object' && tch.name !== null) {
            nameStr = (isRtl ? tch.name.ar || tch.name.en : tch.name.en || tch.name.ar) || ''
          }
          return {
            id: tch.id || tch._id || tch.teacher_id,
            name: nameStr || (isRtl ? 'معلم' : 'Teacher'),
          }
        })
        setTeachers(formatted)
      } catch (err) {
        console.warn('Failed to fetch teachers for sessions dropdown:', err)
      }
    }
    loadTeachers()
    return () => { active = false }
  }, [isRtl])

  const loadSessions = useCallback(async () => {
    setIsLoading(true)
    try {
      const res = await adminSessionsApi.fetchSessions({
        page: currentPage,
        limit: itemsPerPage,
        status: activeTab === 'all' ? undefined : activeTab,
        search: debouncedSearch,
      })
      if (res && res.success) {
        setSessions(res.data || [])
        if (res.statistics) {
          setApiStats(res.statistics)
        }
        if (res.pagination) {
          setTotalPages(res.pagination.numberOfPages || Math.max(1, Math.ceil((res.pagination.totalCount || res.data.length) / itemsPerPage)))
          setTotalCount(res.pagination.totalCount ?? res.data.length)
        } else {
          setTotalCount(res.data.length)
          setTotalPages(Math.max(1, Math.ceil(res.data.length / itemsPerPage)))
        }
      } else {
        setSessions([])
        setTotalCount(0)
        setTotalPages(1)
      }
    } catch (err) {
      console.error('Failed to fetch sessions:', err)
      setSessions([])
      setTotalCount(0)
      setTotalPages(1)
    } finally {
      setIsLoading(false)
    }
  }, [currentPage, itemsPerPage, activeTab, debouncedSearch])

  useEffect(() => {
    loadSessions()
  }, [loadSessions])

  const stats = useMemo(() => {
    const list = Array.isArray(sessions) ? sessions : []
    return {
      live: Number(apiStats?.in_progress ?? list.filter((s) => s.status === 'live').length) || 0,
      scheduled: Number(apiStats?.scheduled ?? list.filter((s) => s.status === 'scheduled').length) || 0,
      completed: Number(apiStats?.completed ?? list.filter((s) => s.status === 'completed').length) || 0,
      cancelled: Number(apiStats?.cancelled ?? list.filter((s) => s.status === 'cancelled').length) || 0,
    }
  }, [apiStats, sessions])

  const handleTogglePanel = (sessionId, panel) => {
    if (expandedRow === sessionId && expandedPanel === panel) {
      setExpandedRow(null)
      setExpandedPanel(null)
    } else {
      setExpandedRow(sessionId)
      setExpandedPanel(panel)
    }
  }

  const handleReschedule = async (sessionId, payloadOrDate, maybeStartTime, maybeEndTime) => {
    const payload =
      typeof payloadOrDate === 'object' && payloadOrDate !== null
        ? payloadOrDate
        : { date: payloadOrDate, startTime: maybeStartTime, endTime: maybeEndTime }

    const res = await adminSessionsApi.rescheduleSession(sessionId, payload)
    if (res && res.success) {
      showSuccessToast(t('adminDashboard.sessions.rescheduleSuccess', 'تمت إعادة جدولة الحصة بنجاح'), isRtl)
      setSessions((prev) =>
        prev.map((s) => {
          if (s.id !== sessionId) return s
          const timeDisplay = payload.endTime ? `${payload.startTime} - ${payload.endTime}` : payload.startTime
          return {
            ...s,
            date: payload.date,
            startTime: payload.startTime,
            endTime: payload.endTime,
            time: timeDisplay,
          }
        })
      )
      setExpandedRow(null)
      setExpandedPanel(null)
      return true
    } else {
      showErrorToast(
        res?.message || t('adminDashboard.sessions.rescheduleError', 'فشلت عملية إعادة الجدولة'),
        isRtl
      )
      return false
    }
  }

  const handleChangeTeacher = async (sessionId, teacherId, teacherName) => {
    const res = await adminSessionsApi.changeTeacher(sessionId, teacherId, teacherName)
    if (res.success) {
      showSuccessToast(
        res?.message || (isRtl ? 'تم تغيير المعلم بنجاح' : 'Teacher changed successfully'),
        isRtl
      )
      setSessions((prev) =>
        prev.map((s) => (s.id === sessionId ? { ...s, teacher: teacherName, teacherId } : s))
      )
      setExpandedRow(null)
      setExpandedPanel(null)
    } else {
      showErrorToast(
        res?.message || (isRtl ? 'فشلت عملية تغيير المعلم' : 'Failed to change teacher'),
        isRtl
      )
    }
  }

  const handleCancelSession = async (sessionId) => {
    const res = await adminSessionsApi.cancelSession(sessionId)
    if (res.success) {
      showSuccessToast(
        res?.message || (isRtl ? 'تم إلغاء الحصة بنجاح' : 'Session cancelled successfully'),
        isRtl
      )
      setSessions((prev) =>
        prev.map((s) => (s.id === sessionId ? { ...s, status: 'cancelled' } : s))
      )
      setExpandedRow(null)
      setExpandedPanel(null)
    } else {
      showErrorToast(
        res?.message || (isRtl ? 'فشلت عملية إلغاء الحصة' : 'Failed to cancel session'),
        isRtl
      )
    }
  }

  const getTabLabel = (key, defaultLabel) => {
    const map = {
      'all': t('adminDashboard.sessions.tabs.all', 'الكل'),
      'scheduled': t('adminDashboard.sessions.tabs.scheduled', 'مجدولة'),
      'live': t('adminDashboard.sessions.tabs.live', 'مباشرة الآن'),
      'completed': t('adminDashboard.sessions.tabs.completed', 'مكتملة'),
      'cancelled': t('adminDashboard.sessions.tabs.cancelled', 'ملغاة'),
    }
    return map[key] || defaultLabel
  }

  const startIdx = totalCount > 0 ? (currentPage - 1) * itemsPerPage + 1 : 0
  const endIdx = totalCount > 0 ? Math.min(currentPage * itemsPerPage, totalCount) : 0
  const isPaginationDimmed = totalPages <= 1

  return (
    <div className="space-y-6 p-1 md:p-6 relative" dir={isRtl ? 'rtl' : 'ltr'}>
      {isLoading && (
        <div className="absolute inset-0 z-50 flex items-center justify-center bg-white/50 dark:bg-slate-900/50 backdrop-blur-sm rounded-3xl">
          <Spinner />
        </div>
      )}
      <div className="text-start">
        <h1 className="text-2xl font-bold text-slate-800 dark:text-white">
          {t('adminDashboard.sessions.title', 'إدارة الحصص الدراسية')}
        </h1>
        <p className="text-sm text-slate-400 dark:text-slate-500 mt-1">
          {t('adminDashboard.sessions.subtitle', 'منارة العز أكاديمي · لوحة الإدارة')}
        </p>
      </div>

      <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
        <StatCard
          label={t('adminDashboard.sessions.scheduled', 'حصص مجدولة')}
          value={stats.scheduled}
          color="blue"
        />
        <StatCard
          label={t('adminDashboard.sessions.liveNow', 'مباشر الآن')}
          value={stats.live}
          color="red"
        />
        <StatCard
          label={t('adminDashboard.sessions.completed', 'حصص مكتملة')}
          value={stats.completed}
          color="green"
        />
        <StatCard
          label={t('adminDashboard.sessions.cancelled', 'ملغاة')}
          value={stats.cancelled}
          color="amber"
        />
      </div>

      <div className="bg-white dark:bg-slate-900 rounded-3xl border border-slate-100 dark:border-slate-800/60 shadow-soft overflow-hidden">
        <div className="p-4 border-b border-slate-100 dark:border-slate-800">
          <div className="relative max-w-md mx-auto">
            <Search size={16} className={`absolute ${isRtl ? 'right-3' : 'left-3'} top-1/2 -translate-y-1/2 text-slate-400 pointer-events-none`} />
            <input
              type="text"
              placeholder={t('adminDashboard.sessions.searchPlaceholder', 'بحث باسم المجموعة أو المعلم أو عنوان الحصة...')}
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className={`w-full bg-[#f3f7f6] dark:bg-slate-800 rounded-2xl py-2.5 ${isRtl ? 'pr-9 pl-9' : 'pl-9 pr-9'} text-sm text-slate-700 dark:text-slate-200 outline-none border border-transparent focus:border-brand-400 transition-colors placeholder-slate-400`}
            />
            {searchQuery && (
              <button
                type="button"
                onClick={() => setSearchQuery('')}
                className={`absolute ${isRtl ? 'left-3' : 'right-3'} top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600 p-0.5 cursor-pointer`}
              >
                <X size={14} />
              </button>
            )}
          </div>
        </div>

        <div className="flex items-center gap-2 px-4 py-3 border-b border-slate-100 dark:border-slate-800 overflow-x-auto">
          {STATUS_TABS.map((tab) => (
            <button
              key={tab.key}
              onClick={() => { setActiveTab(tab.key); setCurrentPage(1) }}
              className={`shrink-0 px-4 py-2 rounded-xl text-sm font-semibold transition-all cursor-pointer ${
                activeTab === tab.key
                  ? 'bg-brand-500 text-white shadow-sm shadow-brand-500/20'
                  : 'bg-[#f3f7f6] dark:bg-slate-800 text-slate-600 dark:text-slate-300 hover:bg-slate-200 dark:hover:bg-slate-700'
              }`}
            >
              {getTabLabel(tab.key, tab.label)}
            </button>
          ))}
        </div>

        <div className="hidden md:grid grid-cols-[2.5fr_1.8fr_1.3fr_1.4fr_0.9fr_1.1fr_2.2fr] gap-3 px-5 py-3 border-b border-slate-100 dark:border-slate-800 bg-slate-50 dark:bg-slate-800/40 text-xs font-bold text-slate-500 dark:text-slate-400">
          <span className="text-start">{t('adminDashboard.sessions.headers.group', 'المجموعة والحصة')}</span>
          <span className="text-start">{t('adminDashboard.sessions.headers.teacher', 'المعلم')}</span>
          <span className="text-start">{t('adminDashboard.sessions.headers.date', 'التاريخ واليوم')}</span>
          <span className="text-start">{t('adminDashboard.sessions.headers.time', 'الوقت والمدة')}</span>
          <span className="text-center">{t('adminDashboard.sessions.headers.count', 'عدد الطلاب')}</span>
          <span className="text-center">{t('adminDashboard.sessions.headers.status', 'الحالة')}</span>
          <span className="text-end">{t('adminDashboard.sessions.headers.actions', 'الإجراءات')}</span>
        </div>

        <div className="divide-y divide-slate-50 dark:divide-slate-800/50">
          {sessions.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-16 gap-3 text-slate-400">
              <Calendar size={40} strokeWidth={1.5} />
              <p className="text-sm font-medium">{t('adminDashboard.sessions.noSessionsFound', 'لا توجد حصص مطابقة')}</p>
            </div>
          ) : (
            sessions.map((session) => (
              <SessionRow
                key={session.id}
                session={session}
                isExpanded={expandedRow === session.id}
                expandedPanel={expandedPanel}
                handleTogglePanel={handleTogglePanel}
                handleReschedule={handleReschedule}
                handleChangeTeacher={handleChangeTeacher}
                handleCancelSession={handleCancelSession}
                teachers={teachers}
                t={t}
              />
            ))
          )}
        </div>

        <div
          className={`flex flex-col sm:flex-row items-center justify-between gap-4 p-5 bg-white dark:bg-slate-900 border-t border-slate-100 dark:border-slate-800 rounded-b-3xl transition-opacity duration-300 ${
            isPaginationDimmed ? 'opacity-40 pointer-events-none select-none' : ''
          }`}
        >
          <div className="text-sm text-slate-400 dark:text-slate-500 font-medium">
            {isRtl ? (
              <>
                {t('adminDashboard.students.pagination.showing', 'عرض')}{' '}
                <span className="font-semibold text-slate-700 dark:text-slate-200">{startIdx}</span>{' '}
                {t('adminDashboard.students.pagination.to', 'إلى')}{' '}
                <span className="font-semibold text-slate-700 dark:text-slate-200">{endIdx}</span>{' '}
                {t('adminDashboard.students.pagination.of', 'من أصل')}{' '}
                <span className="font-semibold text-slate-700 dark:text-slate-200">{totalCount}</span>{' '}
                {t('adminDashboard.sessions.title', 'حصص')}
              </>
            ) : (
              <>
                {t('adminDashboard.students.pagination.showing', 'Showing')}{' '}
                <span className="font-semibold text-slate-700 dark:text-slate-200">{startIdx}</span>{' '}
                {t('adminDashboard.students.pagination.to', 'to')}{' '}
                <span className="font-semibold text-slate-700 dark:text-slate-200">{endIdx}</span>{' '}
                {t('adminDashboard.students.pagination.of', 'of')}{' '}
                <span className="font-semibold text-slate-700 dark:text-slate-200">{totalCount}</span>{' '}
                {t('adminDashboard.sessions.title', 'sessions')}
              </>
            )}
          </div>

          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={() => setCurrentPage((prev) => Math.max(prev - 1, 1))}
              disabled={currentPage === 1 || isPaginationDimmed}
              className="flex items-center gap-1.5 px-4 py-2 rounded-xl text-xs sm:text-sm font-semibold border border-slate-100 dark:border-slate-800 bg-white hover:bg-slate-50 dark:bg-slate-900 dark:hover:bg-slate-800 text-slate-700 dark:text-slate-300 disabled:opacity-40 disabled:cursor-not-allowed transition-all cursor-pointer"
            >
              {isRtl ? <ChevronRight size={16} aria-hidden="true" /> : <ChevronLeft size={16} aria-hidden="true" />}
            </button>

            <span className="px-3 py-2 rounded-xl text-xs sm:text-sm font-bold border border-slate-100 dark:border-slate-800 bg-white dark:bg-slate-900 text-slate-700 dark:text-slate-300 min-w-[80px] text-center">
              {currentPage} / {totalPages}
            </span>

            <button
              type="button"
              onClick={() => setCurrentPage((prev) => Math.min(prev + 1, totalPages))}
              disabled={currentPage === totalPages || isPaginationDimmed}
              className="flex items-center gap-1.5 px-4 py-2 rounded-xl text-xs sm:text-sm font-semibold border border-slate-100 dark:border-slate-800 bg-white hover:bg-slate-50 dark:bg-slate-900 dark:hover:bg-slate-800 text-slate-700 dark:text-slate-300 disabled:opacity-40 disabled:cursor-not-allowed transition-all cursor-pointer"
            >
              {isRtl ? <ChevronLeft size={16} aria-hidden="true" /> : <ChevronRight size={16} aria-hidden="true" />}
            </button>
          </div>
        </div>
      </div>
    </div>
  )
}

import { useState, useEffect, useMemo } from 'react'
import { useNavigate } from 'react-router-dom'
import { useTranslation } from 'react-i18next'
import { useQuery, useQueryClient } from '@tanstack/react-query'
import { toast } from 'react-hot-toast'
import { teachersApi } from '@/shared/services/api/teachersApi'
import { showDeleteConfirm } from '@/shared/utils/sweetAlert'
import TeachersList from './components/TeachersList'
import TeacherProfileCard from './components/TeacherProfileCard'
import AddEditTeacherScreen from './components/AddEditTeacherScreen'
import TeacherDetailsScreen from './components/TeacherDetailsScreen'
import Spinner from '@/shared/components/Spinner'

export default function AdminTeachers() {
  const navigate = useNavigate()
  const { t, i18n } = useTranslation()
  const isRtl = i18n.language.startsWith('ar')

  const queryClient = useQueryClient()
  const [viewMode, setViewMode] = useState('list')
  const [selectedTeacherId, setSelectedTeacherId] = useState(null)
  const [selectedTeacherRecord, setSelectedTeacherRecord] = useState(null)
  const [isSavingTeacher, setIsSavingTeacher] = useState(false)

  const [currentPage, setCurrentPage] = useState(1)
  const [searchVal, setSearchVal] = useState('')
  const [committedSearch, setCommittedSearch] = useState('')
  const [statusFilter, setStatusFilter] = useState('all')

  useEffect(() => {
    setCurrentPage(1)
  }, [committedSearch, statusFilter])

  const handleSearchSubmit = () => {
    setCommittedSearch(searchVal.trim())
    setCurrentPage(1)
  }

  const handleClearSearch = () => {
    setSearchVal('')
    setCommittedSearch('')
    setCurrentPage(1)
  }

  const { data: res, isLoading, isFetching } = useQuery({
    queryKey: ['teachers', currentPage, committedSearch, statusFilter],
    queryFn: () =>
      teachersApi.fetchTeachers({
        page: currentPage,
        limit: 10,
        search: committedSearch,
        status: statusFilter !== 'all' ? statusFilter : undefined
      }),
    staleTime: 60 * 1000,
  })

  const teachers = useMemo(() => res?.data || [], [res])
  const pagination = res?.pagination || { currentPage: 1, limit: 10, numberOfPages: 1 }
  const statistics = res?.statistics || {
    total: teachers.length,
    active: teachers.filter((t) => t.active).length,
    stopped: teachers.filter((t) => !t.active).length
  }

  useEffect(() => {
    if (teachers.length > 0 && (!selectedTeacherId || !teachers.some((t) => t.id === selectedTeacherId))) {
      setSelectedTeacherId(teachers[0].id)
    }
  }, [teachers, selectedTeacherId])

  const selectedTeacher = useMemo(() => {
    return teachers.find((t) => t.id === selectedTeacherId) || teachers[0] || null
  }, [teachers, selectedTeacherId])

  const handleToggleStatus = async (idOrTeacher) => {
    const teacher = (typeof idOrTeacher === 'object' && idOrTeacher !== null)
      ? idOrTeacher
      : (teachers.find((t) => t.id === idOrTeacher || t.teacher_id === idOrTeacher) ||
         (selectedTeacherRecord?.id === idOrTeacher || selectedTeacherRecord?.teacher_id === idOrTeacher ? selectedTeacherRecord : null))
    if (!teacher) return
    const id = teacher.id || teacher.teacher_id
    const newActive = !teacher.active

    try {
      await teachersApi.toggleTeacherStatus(teacher)
      await queryClient.invalidateQueries({ queryKey: ['teachers'] })
      setSelectedTeacherRecord((prev) =>
        prev && (prev.id === id || prev.teacher_id === id)
          ? { ...prev, active: newActive, status: newActive ? 'Active' : 'Suspended' }
          : prev
      )
      toast.success(
        newActive
          ? (isRtl ? 'تم تفعيل حساب المعلم بنجاح' : 'Teacher account activated')
          : (isRtl ? 'تم إيقاف حساب المعلم' : 'Teacher account suspended')
      )
    } catch (err) {
      const backendMsg = err.response?.data?.message
      const errorText = Array.isArray(backendMsg)
        ? backendMsg.join(' - ')
        : (backendMsg || (isRtl ? 'حدث خطأ أثناء تحديث حالة المعلم' : 'Failed to update teacher status'))
      toast.error(errorText)
      console.error('Failed to toggle status:', err)
    }
  }

  const handleDeleteTeacher = async (teacher) => {
    if (!teacher) return
    const id = teacher.teacher_id || teacher.id || teacher._id
    const teacherName = typeof teacher.name === 'object' && teacher.name !== null
      ? ((isRtl ? teacher.name.ar : teacher.name.en) || teacher.name.ar || teacher.name.en || 'المعلم')
      : (teacher.name || 'المعلم')

    const isConfirmed = await showDeleteConfirm(isRtl, teacherName)
    if (!isConfirmed) return

    try {
      await teachersApi.deleteTeacher(id)
      await queryClient.invalidateQueries({ queryKey: ['teachers'] })
      toast.success(isRtl ? 'تم حذف المعلم بنجاح' : 'Teacher deleted successfully')

      if (selectedTeacherId === id) {
        setSelectedTeacherId(null)
      }
      if (selectedTeacherRecord && (selectedTeacherRecord.id === id || selectedTeacherRecord.teacher_id === id)) {
        setSelectedTeacherRecord(null)
        setViewMode('list')
      }
    } catch (err) {
      toast.error(isRtl ? 'حدث خطأ أثناء حذف المعلم' : 'Failed to delete teacher')
      console.error('Failed to delete teacher:', err)
    }
  }

  const handleSaveTeacher = async (formData) => {
    const isUpdate = viewMode === 'edit-teacher' && selectedTeacherRecord
    const id = selectedTeacherRecord?.teacher_id || selectedTeacherRecord?.id

    setIsSavingTeacher(true)
    try {
      if (isUpdate) {
        await teachersApi.updateTeacher(id, formData)

        const newRate = Number(formData.hourlyRate)
        const oldRate = Number(selectedTeacherRecord?.hourlyRate)
        if (!isNaN(newRate) && newRate !== oldRate && newRate >= 0) {
          try {
            await teachersApi.updateTeacherHourlyRate(id, newRate)
          } catch (rateErr) {
            console.warn('Hourly rate update failed during teacher edit:', rateErr)
          }
        }

        toast.success(isRtl ? 'تم تحديث بيانات المعلم بنجاح' : 'Teacher updated successfully')
      } else {
        const createRes = await teachersApi.createTeacher(formData)
        toast.success(isRtl ? 'تمت إضافة المعلم بنجاح' : 'Teacher added successfully')
        if (createRes?.data?.id) {
          setSelectedTeacherId(createRes.data.id)
        }
      }
      await queryClient.invalidateQueries({ queryKey: ['teachers'] })
      setSelectedTeacherRecord(null)
      setViewMode('list')
    } catch (err) {
      const backendMsg = err.response?.data?.message
      const errorText = Array.isArray(backendMsg)
        ? backendMsg.join(' - ')
        : (backendMsg || (isRtl ? 'حدث خطأ أثناء حفظ بيانات المعلم' : 'Failed to save teacher'))
      toast.error(errorText)
      console.error('Failed to save teacher:', err)
    } finally {
      setIsSavingTeacher(false)
    }
  }

  const handleOpenEditScreen = (teacher) => {
    setSelectedTeacherRecord(teacher)
    setViewMode('edit-teacher')
  }

  const handleViewDetails = (teacher) => {
    const id = teacher?.teacher_id || teacher?.id || teacher?.user_id || selectedTeacherId
    if (id) {
      navigate(`/dashboard/admin/teachers/${id}`)
    } else {
      setSelectedTeacherRecord(teacher)
      setViewMode('view-teacher')
    }
  }

  return (
    <div className="space-y-8 p-1 md:p-6 relative" dir={isRtl ? 'rtl' : 'ltr'}>
      {isLoading && viewMode === 'list' && (
        <div className="absolute inset-0 z-50 flex items-center justify-center bg-white/50 dark:bg-slate-900/50 backdrop-blur-sm rounded-3xl">
          <Spinner />
        </div>
      )}

      {viewMode === 'list' && (
        <>
          <div className="text-start">
            <h1 className="text-2xl font-bold text-slate-800 dark:text-white">
              {t('adminDashboard.teachers.title', 'إدارة المعلمين')}
            </h1>
            <p className="text-sm text-slate-400 dark:text-slate-500 mt-1">
              {t('adminDashboard.teachers.subtitle', 'منارة العز أكاديمي · لوحة الإدارة')}
            </p>
          </div>

           <div className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-3">
            <button
              type="button"
              onClick={() => setStatusFilter('all')}
              className={`flex items-center justify-between p-6 bg-white dark:bg-slate-900 rounded-3xl border transition-all text-start cursor-pointer hover:shadow-md ${
                statusFilter === 'all'
                  ? 'border-[#005953] ring-2 ring-[#005953]/20 shadow-soft'
                  : 'border-slate-100 dark:border-slate-800/60 shadow-soft'
              }`}
            >
              <div>
                <span className="text-xs font-bold text-slate-400 dark:text-slate-500 block">
                  {t('adminDashboard.teachers.total', 'إجمالي المعلمين')}
                </span>
                <span className="text-xs text-slate-400 mt-1 block">
                  {isRtl ? 'عرض جميع المعلمين' : 'View all teachers'}
                </span>
              </div>
              <span className="text-3xl font-extrabold text-slate-700 dark:text-slate-200">
                {statistics.total ?? 0}
              </span>
            </button>

            <button
              type="button"
              onClick={() => setStatusFilter('active')}
              className={`flex items-center justify-between p-6 bg-white dark:bg-slate-900 rounded-3xl border transition-all text-start cursor-pointer hover:shadow-md ${
                statusFilter === 'active'
                  ? 'border-emerald-500 ring-2 ring-emerald-500/20 shadow-soft'
                  : 'border-slate-100 dark:border-slate-800/60 shadow-soft'
              }`}
            >
              <div>
                <span className="text-xs font-bold text-slate-400 dark:text-slate-500 block">
                  {t('adminDashboard.teachers.active', 'نشطون')}
                </span>
                <span className="text-xs text-emerald-600/70 mt-1 block">
                  {isRtl ? 'المعلمون النشطون فقط' : 'Active teachers only'}
                </span>
              </div>
              <span className="text-3xl font-extrabold text-emerald-600 dark:text-emerald-400">
                {statistics.active ?? 0}
              </span>
            </button>

            <button
              type="button"
              onClick={() => setStatusFilter('stopped')}
              className={`flex items-center justify-between p-6 bg-white dark:bg-slate-900 rounded-3xl border transition-all text-start cursor-pointer hover:shadow-md ${
                statusFilter === 'stopped'
                  ? 'border-rose-500 ring-2 ring-rose-500/20 shadow-soft'
                  : 'border-slate-100 dark:border-slate-800/60 shadow-soft'
              }`}
            >
              <div>
                <span className="text-xs font-bold text-slate-400 dark:text-slate-500 block">
                  {t('adminDashboard.teachers.suspended', 'موقوفون')}
                </span>
                <span className="text-xs text-rose-500/70 mt-1 block">
                  {isRtl ? 'الحسابات الموقوفة' : 'Stopped / Suspended'}
                </span>
              </div>
              <span className="text-3xl font-extrabold text-rose-600 dark:text-rose-400">
                {statistics.stopped ?? 0}
              </span>
            </button>
          </div>

          <div className="flex flex-col lg:flex-row gap-8 items-start">
             <div className="w-full lg:w-80 shrink-0">
              <TeacherProfileCard
                teacher={selectedTeacher}
                isRtl={isRtl}
                t={t}
                onEdit={handleOpenEditScreen}
                onToggleStatus={handleToggleStatus}
                onDelete={handleDeleteTeacher}
                onViewDetails={handleViewDetails}
              />
            </div>

             <div className="flex-1 w-full">
              <TeachersList
                teachers={teachers}
                selectedTeacherId={selectedTeacherId}
                isRtl={isRtl}
                t={t}
                searchVal={searchVal}
                onSearchChange={setSearchVal}
                committedSearch={committedSearch}
                onSearchSubmit={handleSearchSubmit}
                onClearSearch={handleClearSearch}
                statusFilter={statusFilter}
                onStatusFilterChange={setStatusFilter}
                statistics={statistics}
                currentPage={currentPage}
                totalPages={pagination.numberOfPages || 1}
                totalItems={statistics.total || teachers.length}
                isFetching={isFetching}
                onPageChange={setCurrentPage}
                onSelectTeacher={setSelectedTeacherId}
                onOpenAddScreen={() => setViewMode('add-teacher')}
                onOpenEditScreen={handleOpenEditScreen}
                onViewDetails={handleViewDetails}
                onDelete={handleDeleteTeacher}
                onToggleStatus={handleToggleStatus}
              />
            </div>
          </div>
        </>
      )}

      {(viewMode === 'add-teacher' || viewMode === 'edit-teacher') && (
        <AddEditTeacherScreen
          teacher={viewMode === 'edit-teacher' ? selectedTeacherRecord : null}
          isRtl={isRtl}
          t={t}
          isSaving={isSavingTeacher}
          onSave={handleSaveTeacher}
          onCancel={() => {
            setSelectedTeacherRecord(null)
            setViewMode('list')
          }}
        />
      )}

      {viewMode === 'view-teacher' && (
        <TeacherDetailsScreen
          teacher={selectedTeacherRecord}
          isRtl={isRtl}
          t={t}
          onCancel={() => {
            setSelectedTeacherRecord(null)
            setViewMode('list')
          }}
          onToggleStatus={handleToggleStatus}
          onDelete={handleDeleteTeacher}
          onEdit={(teacher) => {
            setSelectedTeacherRecord(teacher)
            setViewMode('edit-teacher')
          }}
        />
      )}
    </div>
  )
}

import { useState, useEffect, useRef } from 'react'
import { X, FileText, Upload, Loader2, Check, ExternalLink, RefreshCw } from 'lucide-react'
import { toast } from 'react-hot-toast'
import { teachersApi } from '@/shared/services/api/teachersApi'

export default function EditCertificateModal({
  isOpen,
  onClose,
  teacherId,
  certificate,
  isRtl,
  onSuccess
}) {
  const [nameAr, setNameAr] = useState('')
  const [nameEn, setNameEn] = useState('')
  const [replacementFile, setReplacementFile] = useState(null)
  const [replacementPreview, setReplacementPreview] = useState(null)
  const [isSubmitting, setIsSubmitting] = useState(false)
  const fileInputRef = useRef(null)

  useEffect(() => {
    if (certificate) {
      const curNameAr = certificate.nameAr || (typeof certificate.name === 'object' ? certificate.name?.ar : certificate.name) || ''
      const curNameEn = certificate.nameEn || (typeof certificate.name === 'object' ? certificate.name?.en : '') || ''
      setNameAr(curNameAr)
      setNameEn(curNameEn)
      setReplacementFile(null)
      setReplacementPreview(null)
    }
  }, [certificate, isOpen])

  if (!isOpen || !certificate) return null

  const certId = certificate.id || certificate._id
  const currentFile = certificate.file || certificate.image || certificate.url

  const handleFileChange = (e) => {
    const file = e.target.files?.[0]
    if (!file) return

    setReplacementFile(file)
    if (file.type.startsWith('image/')) {
      const url = URL.createObjectURL(file)
      setReplacementPreview(url)
    } else {
      setReplacementPreview(null)
    }
  }

  const handleSubmit = async (e) => {
    e.preventDefault()

    if (!nameAr.trim()) {
      toast.error(isRtl ? 'يرجى إدخال اسم الشهادة بالعربية' : 'Please enter certificate name in Arabic')
      return
    }

    try {
      setIsSubmitting(true)

      const payload = {
        name: {
          ar: nameAr.trim(),
          en: (nameEn || nameAr).trim()
        },
        nameAr: nameAr.trim(),
        nameEn: (nameEn || nameAr).trim(),
      }

      if (replacementFile) {
        payload.file = replacementFile
      }

      await teachersApi.updateTeacherCertificate(teacherId, certId, payload)
      toast.success(isRtl ? 'تم تحديث بيانات الشهادة بنجاح!' : 'Certificate updated successfully!')
      if (onSuccess) onSuccess()
      onClose()
    } catch (err) {
      const backendMsg = err.response?.data?.message
      const errorText = Array.isArray(backendMsg)
        ? backendMsg.join(' - ')
        : (backendMsg || (isRtl ? 'حدث خطأ أثناء تعديل الشهادة' : 'Failed to update certificate'))
      toast.error(errorText)
      console.error('Failed to update certificate:', err)
    } finally {
      setIsSubmitting(false)
    }
  }

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-fadeIn"
      dir={isRtl ? 'rtl' : 'ltr'}
      onClick={onClose}
    >
      <div
        className="bg-white dark:bg-slate-900 rounded-3xl max-w-lg w-full shadow-2xl border border-slate-100 dark:border-slate-800 overflow-hidden transform transition-all text-start"
        onClick={(e) => e.stopPropagation()}
      >
         <div className="bg-[#005953] px-6 py-4 flex items-center justify-between text-white">
          <div className="flex items-center gap-2.5">
            <div className="p-2 bg-white/10 rounded-xl">
              <RefreshCw size={18} />
            </div>
            <div>
              <h3 className="text-base font-bold">
                {isRtl ? 'تعديل الشهادة أو استبدال الملف' : 'Update Certificate / Replace File'}
              </h3>
              <p className="text-xs text-emerald-100 font-medium">
                {certificate.name || (isRtl ? 'تعديل وثيقة المعلم' : 'Edit Teacher Document')}
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="p-1.5 rounded-full hover:bg-white/20 transition-colors cursor-pointer"
          >
            <X size={18} />
          </button>
        </div>

         <form onSubmit={handleSubmit} className="p-6 space-y-4">
          <div className="space-y-1.5">
            <label className="block text-xs font-bold text-slate-700 dark:text-slate-300">
              {isRtl ? 'اسم الشهادة (بالعربية)' : 'Certificate Name (Arabic)'} *
            </label>
            <input
              type="text"
              required
              value={nameAr}
              onChange={(e) => setNameAr(e.target.value)}
              placeholder={isRtl ? 'مثال: إجازة متقدمة في متن الجزرية' : 'e.g. Al-Jazariyyah Certification'}
              className="w-full px-4 py-2.5 rounded-2xl bg-slate-50 dark:bg-slate-850 border border-slate-200 dark:border-slate-750 text-slate-900 dark:text-white font-semibold text-sm focus:outline-none focus:ring-2 focus:ring-[#005953] transition-all"
            />
          </div>

          <div className="space-y-1.5">
            <label className="block text-xs font-bold text-slate-700 dark:text-slate-300">
              {isRtl ? 'اسم الشهادة (بالإنجليزية - اختياري)' : 'Certificate Name (English - Optional)'}
            </label>
            <input
              type="text"
              value={nameEn}
              onChange={(e) => setNameEn(e.target.value)}
              placeholder="e.g. Advanced Al-Jazariyyah Certification"
              className="w-full px-4 py-2.5 rounded-2xl bg-slate-50 dark:bg-slate-850 border border-slate-200 dark:border-slate-750 text-slate-900 dark:text-white font-semibold text-sm focus:outline-none focus:ring-2 focus:ring-[#005953] transition-all"
            />
          </div>

           {currentFile && (
            <div className="p-3 bg-slate-50 dark:bg-slate-850 rounded-2xl border border-slate-200 dark:border-slate-800 flex items-center justify-between">
              <div className="flex items-center gap-2.5 min-w-0">
                <FileText size={18} className="text-amber-500 shrink-0" />
                <div className="min-w-0">
                  <span className="block text-[11px] font-bold text-slate-500">
                    {isRtl ? 'الملف الحالي:' : 'Current File:'}
                  </span>
                  <span className="block text-xs font-extrabold text-slate-800 dark:text-slate-200 truncate max-w-[220px]">
                    {certificate.name || 'ملف الشهادة'}
                  </span>
                </div>
              </div>
              <a
                href={currentFile}
                target="_blank"
                rel="noreferrer"
                className="flex items-center gap-1 px-3 py-1.5 bg-white dark:bg-slate-800 hover:bg-slate-100 dark:hover:bg-slate-700 text-[#005953] dark:text-emerald-400 rounded-xl text-xs font-bold border border-slate-200 dark:border-slate-700 transition-colors"
              >
                <span>{isRtl ? 'معاينة' : 'Preview'}</span>
                <ExternalLink size={12} />
              </a>
            </div>
          )}

           <div className="space-y-1.5">
            <label className="block text-xs font-bold text-slate-700 dark:text-slate-300">
              {isRtl ? 'استبدال الملف بملف جديد (اختياري)' : 'Replace With New File (Optional)'}
            </label>
            <div
              onClick={() => fileInputRef.current?.click()}
              className={`border-2 border-dashed rounded-2xl p-4 text-center cursor-pointer transition-all ${
                replacementFile
                  ? 'border-emerald-500 bg-emerald-50/20 dark:bg-emerald-950/20'
                  : 'border-slate-200 dark:border-slate-800 hover:border-[#005953] bg-slate-50/50 dark:bg-slate-950/20'
              }`}
            >
              <input
                ref={fileInputRef}
                type="file"
                accept=".pdf,.png,.jpg,.jpeg,.webp"
                className="hidden"
                onChange={handleFileChange}
              />

              {replacementFile ? (
                <div className="flex items-center justify-center gap-3">
                  {replacementPreview ? (
                    <img
                      src={replacementPreview}
                      alt="preview"
                      className="w-12 h-12 rounded-xl object-cover border border-emerald-300"
                    />
                  ) : (
                    <div className="p-3 bg-emerald-100 dark:bg-emerald-900/40 text-emerald-700 dark:text-emerald-300 rounded-xl">
                      <FileText size={24} />
                    </div>
                  )}
                  <div className="text-start">
                    <p className="text-xs font-bold text-slate-800 dark:text-slate-200 truncate max-w-[200px]">
                      {replacementFile.name}
                    </p>
                    <p className="text-[10px] text-emerald-600 dark:text-emerald-400 font-bold">
                      {isRtl ? 'ملف الاستبدال جاهز' : 'Replacement file ready'} ({(replacementFile.size / (1024 * 1024)).toFixed(2)} MB)
                    </p>
                  </div>
                </div>
              ) : (
                <div className="space-y-1 py-1">
                  <Upload size={20} className="mx-auto text-slate-400" />
                  <p className="text-xs font-bold text-slate-600 dark:text-slate-300">
                    {isRtl ? 'اضغط هنا لرفع ملف بديل' : 'Click here to upload replacement file'}
                  </p>
                  <p className="text-[10px] text-slate-400">
                    {isRtl ? 'اتركه فارغاً إذا كنت تريد تعديل الاسم فقط' : 'Leave empty to keep current file'}
                  </p>
                </div>
              )}
            </div>
          </div>

           <div className="flex items-center justify-end gap-3 pt-3 border-t border-slate-100 dark:border-slate-800">
            <button
              type="button"
              onClick={onClose}
              disabled={isSubmitting}
              className="px-5 py-2.5 rounded-xl text-xs font-bold text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors cursor-pointer"
            >
              {isRtl ? 'إلغاء' : 'Cancel'}
            </button>
            <button
              type="submit"
              disabled={isSubmitting}
              className="flex items-center gap-2 px-6 py-2.5 bg-[#005953] hover:bg-[#004742] text-white rounded-xl text-xs font-bold shadow-md shadow-[#005953]/20 active:scale-95 transition-all cursor-pointer disabled:opacity-50"
            >
              {isSubmitting ? (
                <>
                  <Loader2 size={15} className="animate-spin" />
                  <span>{isRtl ? 'جاري الحفظ...' : 'Saving...'}</span>
                </>
              ) : (
                <>
                  <Check size={15} />
                  <span>{isRtl ? 'حفظ التعديلات' : 'Save Changes'}</span>
                </>
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  )
}

import { useState, useEffect } from 'react'
import { X, DollarSign, Loader2, Check } from 'lucide-react'
import { toast } from 'react-hot-toast'
import { teachersApi } from '@/shared/services/api/teachersApi'

export default function UpdateHourlyRateModal({
  isOpen,
  onClose,
  teacher,
  isRtl = true,
  onSuccess
}) {
  const [hourlyRate, setHourlyRate] = useState('')
  const [isSubmitting, setIsSubmitting] = useState(false)

  useEffect(() => {
    if (teacher && isOpen) {
      setHourlyRate(teacher.hourlyRate !== undefined && teacher.hourlyRate !== null ? String(teacher.hourlyRate) : '0')
    }
  }, [teacher, isOpen])

  if (!isOpen || !teacher) return null

  const teacherId = teacher.teacher_id || teacher.id || teacher._id
  const teacherName = typeof teacher.name === 'object' && teacher.name !== null
    ? (isRtl ? teacher.name.ar : teacher.name.en) || teacher.name.ar || teacher.name.en || ''
    : (teacher.name || '')

  const handleSubmit = async (e) => {
    e.preventDefault()
    const rateNumber = Math.max(0, Number(hourlyRate) || 0)

    try {
      setIsSubmitting(true)
      await teachersApi.updateTeacherHourlyRate(teacherId, rateNumber)
      toast.success(
        isRtl
          ? `تم تحديث سعر الساعة بنجاح إلى ${rateNumber} $`
          : `Hourly rate updated successfully to ${rateNumber} $`
      )
      if (onSuccess) onSuccess(rateNumber)
      onClose()
    } catch (err) {
      const backendMsg = err.response?.data?.message
      const errorText = Array.isArray(backendMsg)
        ? backendMsg.join(' - ')
        : (backendMsg || (isRtl ? 'حدث خطأ أثناء تحديث سعر الساعة' : 'Failed to update hourly rate'))
      toast.error(errorText)
      console.error('Failed to update hourly rate:', err)
    } finally {
      setIsSubmitting(false)
    }
  }

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm animate-fadeIn"
      dir={isRtl ? 'rtl' : 'ltr'}
      onClick={onClose}
    >
      <div
        className="bg-white dark:bg-slate-900 rounded-3xl max-w-md w-full shadow-2xl border border-slate-100 dark:border-slate-800 overflow-hidden transform transition-all text-start"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="bg-[#005953] px-6 py-4 flex items-center justify-between text-white">
          <div className="flex items-center gap-2.5">
            <div className="p-2 bg-white/10 rounded-xl">
              <DollarSign size={18} />
            </div>
            <div>
              <h3 className="text-base font-bold">
                {isRtl ? 'تعديل سعر ساعة المعلم' : 'Update Teacher Hourly Rate'}
              </h3>
              {teacherName && (
                <p className="text-xs text-emerald-100 font-medium">
                  {teacherName}
                </p>
              )}
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="p-1.5 rounded-full hover:bg-white/20 transition-colors cursor-pointer"
          >
            <X size={18} />
          </button>
        </div>

        <form onSubmit={handleSubmit} className="p-6 space-y-5">
          <div className="space-y-2">
            <label className="block text-xs font-bold text-slate-700 dark:text-slate-300">
              {isRtl ? 'سعر الساعة الجديد ($ / ساعة)' : 'New Hourly Rate ($ / hr)'}
            </label>
            <div className="relative">
              <input
                type="number"
                min="0"
                step="1"
                required
                value={hourlyRate}
                onChange={(e) => setHourlyRate(e.target.value)}
                placeholder="90"
                className="w-full px-4 py-3 rounded-2xl bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 text-slate-900 dark:text-white font-extrabold text-lg focus:outline-none focus:ring-2 focus:ring-[#005953] transition-all"
              />
              <span className="absolute end-4 top-1/2 -translate-y-1/2 text-xs font-bold text-slate-400">
                $
              </span>
            </div>
            <p className="text-[11px] text-slate-400 dark:text-slate-500 font-medium">
              {isRtl
                ? `سعر الساعة الحالي: ${teacher.hourlyRate ?? 0} $`
                : `Current rate: ${teacher.hourlyRate ?? 0} $`}
            </p>
          </div>

          <div className="flex items-center justify-end gap-3 pt-3 border-t border-slate-100 dark:border-slate-800">
            <button
              type="button"
              onClick={onClose}
              disabled={isSubmitting}
              className="px-5 py-2.5 rounded-xl text-xs font-bold text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 transition-colors cursor-pointer"
            >
              {isRtl ? 'إلغاء' : 'Cancel'}
            </button>
            <button
              type="submit"
              disabled={isSubmitting}
              className="flex items-center gap-2 px-6 py-2.5 bg-[#005953] hover:bg-[#004742] text-white rounded-xl text-xs font-bold shadow-md shadow-[#005953]/20 active:scale-95 transition-all cursor-pointer disabled:opacity-50"
            >
              {isSubmitting ? (
                <>
                  <Loader2 size={15} className="animate-spin" />
                  <span>{isRtl ? 'جاري الحفظ...' : 'Saving...'}</span>
                </>
              ) : (
                <>
                  <Check size={15} />
                  <span>{isRtl ? 'حفظ السعر' : 'Save Rate'}</span>
                </>
              )}
            </button>
          </div>
        </form>
      </div>
    </div>
  )
}

import { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { z } from 'zod';

import { Loader2 } from 'lucide-react';
import Button from '@/shared/components/Button.jsx';
import CountryPhoneInput from '@/shared/components/CountryPhoneInput.jsx';

const contactSchema = z.object({
  email: z.string().min(1, 'البريد الإلكتروني مطلوب').email('البريد الإلكتروني غير صالح'),
  phone: z.string().min(5, 'رقم الهاتف مطلوب'),
  whatsapp: z.string().min(5, 'رقم الواتساب مطلوب')
});

export default function ContactUsForm({
  contactInfo,
  onSave,
  onCancel,
  isLoading = false,
  isSaving = false,
  canUpdate = true
}) {
  const { t, i18n } = useTranslation();
  const isRtl = i18n.language.startsWith('ar');
  const [errors, setErrors] = useState({});

  const [localContact, setLocalContact] = useState({
    phone: '',
    whatsapp: '',
    email: ''
  });

  useEffect(() => {
    if (contactInfo) {
      setLocalContact({
        phone: contactInfo.phone || '',
        whatsapp: contactInfo.whatsapp || '',
        email: contactInfo.email || ''
      });
    }
  }, [contactInfo]);

  const handleSubmit = (e) => {
    e.preventDefault();
    const result = contactSchema.safeParse(localContact);
    if (!result.success) {
      const formatted = {};
      result.error.issues.forEach(issue => {
        formatted[issue.path[0]] = isRtl ? issue.message : issue.message.replace('مطلوب', 'is required').replace('غير صالح', 'is invalid');
      });
      setErrors(formatted);
      return;
    }
    setErrors({});
    onSave(localContact);
  };

  const handleCancelClick = () => {
    if (contactInfo) {
      setLocalContact({
        phone: contactInfo.phone || '',
        whatsapp: contactInfo.whatsapp || '',
        email: contactInfo.email || ''
      });
    }
    if (onCancel) {
      onCancel();
    }
    setErrors({});
  };

  return (
    <div className="bg-white dark:bg-slate-900 rounded-[2rem] border border-slate-100 dark:border-slate-800/60 shadow-soft p-5 lg:p-8">
      <h2 className="text-xl font-bold text-slate-800 dark:text-slate-100 mb-6 text-start">
        {t('adminDashboard.website.contactUsNumbers', isRtl ? 'ارقام التواصل معنا' : 'Contact Us Numbers')}
      </h2>

      <form onSubmit={handleSubmit} className="space-y-6">
        <div className="grid grid-cols-1 md:grid-cols-3 gap-6 items-end">
          <div className="space-y-2 text-start">
            <label className="text-sm font-semibold text-slate-600 dark:text-slate-400 block px-1">
              {t('common.email', isRtl ? 'البريد الإلكتروني' : 'Email')}
            </label>
            <div className="relative">
              <input
                type="email"
                required
                disabled={!canUpdate || isLoading || isSaving}
                value={localContact.email}
                onChange={(e) => {
                  setLocalContact({ ...localContact, email: e.target.value });
                  if (errors.email) setErrors({ ...errors, email: null });
                }}
                placeholder="ahmed@gmail.com"
                className={`w-full px-5 py-3.5 bg-[#F5F5F2] dark:bg-slate-950 border rounded-2xl focus:bg-white dark:focus:bg-slate-900 focus:ring-1 outline-none text-slate-800 dark:text-slate-200 text-sm font-medium transition-all ${errors.email ? 'border-red-500 focus:border-red-500 focus:ring-red-500' : 'border-transparent dark:border-slate-850 focus:border-[#0f7a6c] focus:ring-[#0f7a6c]'} disabled:opacity-60 disabled:cursor-not-allowed`}
              />
            </div>
            {errors.email && <p className="text-xs text-red-500 font-medium">{errors.email}</p>}
          </div>

          <div className="space-y-2">
            <CountryPhoneInput
              value={localContact.phone}
              disabled={!canUpdate || isLoading || isSaving}
              onChange={(val) => {
                setLocalContact({ ...localContact, phone: val });
                if (errors.phone) setErrors({ ...errors, phone: null });
              }}
              label={t('common.phoneNumber', isRtl ? 'رقم الهاتف' : 'Phone Number')}
            />
            {errors.phone && <p className="text-xs text-red-500 font-medium">{errors.phone}</p>}
          </div>

          <div className="space-y-2">
            <CountryPhoneInput
              value={localContact.whatsapp}
              disabled={!canUpdate || isLoading || isSaving}
              onChange={(val) => {
                setLocalContact({ ...localContact, whatsapp: val });
                if (errors.whatsapp) setErrors({ ...errors, whatsapp: null });
              }}
              label={t('common.whatsapp', isRtl ? 'رقم الواتساب' : 'WhatsApp Number')}
            />
            {errors.whatsapp && <p className="text-xs text-red-500 font-medium">{errors.whatsapp}</p>}
          </div>
        </div>

        {canUpdate && (
          <div className="flex flex-col sm:flex-row items-center justify-start gap-3 border-t border-slate-100 dark:border-slate-800/80 pt-6 mt-6">
            <Button
              type="submit"
              disabled={isSaving || isLoading}
              className="w-full sm:w-auto px-8 py-2.5 bg-[#0f7a6c] hover:bg-[#0c6256] disabled:opacity-70 text-white rounded-xl text-sm font-semibold shadow-sm flex items-center justify-center gap-1.5"
            >
              {isSaving && <Loader2 className="w-4 h-4 animate-spin" />}
              <span>{t('common.modify', isRtl ? 'تعديل' : 'Modify')}</span>
            </Button>
            <Button
              type="button"
              variant="secondary"
              disabled={isSaving || isLoading}
              onClick={handleCancelClick}
              className="w-full sm:w-auto px-6 py-2.5 rounded-xl text-sm text-slate-650 dark:text-slate-300 font-semibold disabled:opacity-50"
            >
              {t('common.cancel', isRtl ? 'إلغاء' : 'Cancel')}
            </Button>
          </div>
        )}
      </form>
    </div>
  );
}

